window.__examData={"exam":"neet","name":"NEET UG","total":290,"sections":[{"name":"Physics","count":103,"questions":[{"id":1382,"text":"If the speed of light is 3 × 10⁸ m/s, the distance traveled by light in one year (light year) is approximately:","options":[{"label":"A","text":"9.46 × 10¹² km"},{"label":"B","text":"9.46 × 10¹² km"},{"label":"C","text":"9.46 × 10¹⁵ km"},{"label":"D","text":"3 × 108 km"}],"answer":1,"solution":"1 light year = 9.46 × 10¹² km."},{"id":1383,"text":"A force of 10 N acts on a body of mass 2 kg for 5 s. The impulse is:","options":[{"label":"A","text":"10 Ns"},{"label":"B","text":"50 Ns"},{"label":"C","text":"2 Ns"},{"label":"D","text":"25 Ns"}],"answer":1,"solution":"Impulse = F × t = 10 × 5 = 50 Ns."},{"id":1384,"text":"The internal resistance of an ideal voltmeter is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"Low"},{"label":"C","text":"Infinity"},{"label":"D","text":"1 Ω"}],"answer":2,"solution":"Ideal voltmeter has infinite resistance to draw zero current."},{"id":1385,"text":"The phenomenon of splitting of light into its constituent colors is called:","options":[{"label":"A","text":"Reflection"},{"label":"B","text":"Refraction"},{"label":"C","text":"Dispersion"},{"label":"D","text":"Diffraction"}],"answer":2,"solution":"Dispersion splits white light into VIBGYOR colors (e.g., rainbow)."},{"id":1386,"text":"Which law states that entropy of an isolated system always increases?","options":[{"label":"A","text":"First law"},{"label":"B","text":"Second law"},{"label":"C","text":"Third law"},{"label":"D","text":"Zeroth law"}],"answer":1,"solution":"Second law: entropy of isolated system always increases (?S = 0)."},{"id":1387,"text":"The time period of a simple pendulum depends on:","options":[{"label":"A","text":"Mass of bob"},{"label":"B","text":"Amplitude (small)"},{"label":"C","text":"Length of pendulum"},{"label":"D","text":"Material of bob"}],"answer":2,"solution":"T = 2pv(L/g). Time period depends only on length and g."},{"id":1388,"text":"The magnetic field at the center of a current carrying circular loop is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"µ0I/2R"},{"label":"C","text":"µ0I/R"},{"label":"D","text":"µ0I/4pR"}],"answer":1,"solution":"B = µ0I/(2R) at center of circular loop."},{"id":1389,"text":"The threshold frequency for a metal is 5 × 10¹⁴ Hz. Its work function is (h = 6.63 × 10⁻³⁴ Js):","options":[{"label":"A","text":"3.315 × 10⁻¹⁹ J"},{"label":"B","text":"3.315 × 10⁻¹⁹ J"},{"label":"C","text":"6.63 × 10⁻¹⁹ J"},{"label":"D","text":"1.99 × 10⁻¹⁹ J"}],"answer":1,"solution":"f = hf0 = 6.63×10⁻³⁴ × 5 × 10¹⁴ = 3.315×10⁻¹⁹ J."},{"id":1390,"text":"The direction of induced current is given by:","options":[{"label":"A","text":"Ampere's law"},{"label":"B","text":"Biot-Savart law"},{"label":"C","text":"Lenz's law"},{"label":"D","text":"Ohm's law"}],"answer":2,"solution":"Lenz's law determines direction: induced current opposes change in flux."},{"id":1391,"text":"Radioactive decay follows which order of kinetics?","options":[{"label":"A","text":"Zero order"},{"label":"B","text":"First order"},{"label":"C","text":"Second order"},{"label":"D","text":"Third order"}],"answer":1,"solution":"Radioactive decay follows first order kinetics: N = N0e???."},{"id":1412,"text":"A particle moves in a circle of radius 2 m with speed 4 m/s. Its centripetal acceleration is:","options":[{"label":"A","text":"2 m/s²"},{"label":"B","text":"8 m/s²"},{"label":"C","text":"4 m/s²"},{"label":"D","text":"16 m/s²"}],"answer":1,"solution":"a_c = v²/r = 16/2 = 8 m/s²."},{"id":1413,"text":"The dimension of Planck's constant is same as:","options":[{"label":"A","text":"Energy"},{"label":"B","text":"Angular momentum"},{"label":"C","text":"Force"},{"label":"D","text":"Power"}],"answer":1,"solution":"h = E/ν ⇒ [ML²T⁻¹] same as angular momentum."},{"id":1414,"text":"A wire of length L and area A has resistance R. If length is halved and area doubled, new resistance is:","options":[{"label":"A","text":"R/2"},{"label":"B","text":"R/4"},{"label":"C","text":"R"},{"label":"D","text":"2R"}],"answer":1,"solution":"R' = ρ(L/2)/(2A) = (ρL/A)/4 = R/4."},{"id":1415,"text":"The angle between electric dipole moment and electric field in stable equilibrium is:","options":[{"label":"A","text":"0°"},{"label":"B","text":"90°"},{"label":"C","text":"180°"},{"label":"D","text":"45°"}],"answer":0,"solution":"In stable equilibrium, p is parallel to E ⇒ θ = 0°, torque = 0."},{"id":1416,"text":"The energy equivalent of 1 amu is:","options":[{"label":"A","text":"931 eV"},{"label":"B","text":"931 MeV"},{"label":"C","text":"931 keV"},{"label":"D","text":"931 J"}],"answer":1,"solution":"1 amu = 931.5 MeV/c²."},{"id":1417,"text":"A lens of power +2 D has focal length:","options":[{"label":"A","text":"0.5 m"},{"label":"B","text":"0.5 m"},{"label":"C","text":"2 m"},{"label":"D","text":"5 m"}],"answer":1,"solution":"f = 1/P = 1/2 = 0.5 m. Positive power → convex lens."},{"id":1418,"text":"A body of mass 5 kg is moving with momentum 20 kg m/s. Its velocity is:","options":[{"label":"A","text":"2 m/s"},{"label":"B","text":"4 m/s"},{"label":"C","text":"100 m/s"},{"label":"D","text":"0.25 m/s"}],"answer":1,"solution":"v = p/m = 20/5 = 4 m/s."},{"id":1419,"text":"In Young's double slit experiment, fringe width depends on:","options":[{"label":"A","text":"Wavelength only"},{"label":"B","text":"Slit width"},{"label":"C","text":"Wavelength, slit distance, and screen distance"},{"label":"D","text":"Screen distance only"}],"answer":2,"solution":"β = λD/d. Depends on λ, D (screen distance), and d (slit separation)."},{"id":1420,"text":"The coefficient of performance of a refrigerator is given by:","options":[{"label":"A","text":"Q1/W"},{"label":"B","text":"Q2/W"},{"label":"C","text":"W/Q1"},{"label":"D","text":"(Q1-Q2)/W"}],"answer":1,"solution":"COP = Q2/W where Q2 is heat extracted from cold reservoir and W is work input."},{"id":1421,"text":"The reason of mirage in desert is:","options":[{"label":"A","text":"Reflection"},{"label":"B","text":"Total internal reflection"},{"label":"C","text":"Diffraction"},{"label":"D","text":"Interference"}],"answer":1,"solution":"Mirage occurs due to total internal reflection of light in layers of different refractive indices."},{"id":1442,"text":"A body starts from rest and moves with uniform acceleration of 2 m/s². The distance covered in 5 seconds is:","options":[{"label":"A","text":"10 m"},{"label":"B","text":"25 m"},{"label":"C","text":"50 m"},{"label":"D","text":"5 m"}],"answer":1,"solution":"s = ut + ½at² = 0 + ½ × 2 × 25 = 25 m."},{"id":1443,"text":"Which of the following has the highest specific heat capacity?","options":[{"label":"A","text":"Iron"},{"label":"B","text":"Copper"},{"label":"C","text":"Water"},{"label":"D","text":"Lead"}],"answer":2,"solution":"Water has the highest specific heat capacity (4200 J/kg°C) among common substances."},{"id":1444,"text":"The SI unit of electric potential is:","options":[{"label":"A","text":"Coulomb"},{"label":"B","text":"Ohm"},{"label":"C","text":"Volt"},{"label":"D","text":"Ampere"}],"answer":2,"solution":"Electric potential is measured in Volts (V = J/C)."},{"id":1445,"text":"A convex mirror always forms which type of image?","options":[{"label":"A","text":"Real and inverted"},{"label":"B","text":"Virtual and erect"},{"label":"C","text":"Real and erect"},{"label":"D","text":"Virtual and inverted"}],"answer":1,"solution":"Convex mirrors always form virtual, erect, and diminished images regardless of object position."},{"id":1446,"text":"The dimensional formula of force is:","options":[{"label":"A","text":"[MLT⁻¹]"},{"label":"B","text":"[ML⁻¹T⁻²]"},{"label":"C","text":"[MLT⁻²]"},{"label":"D","text":"[ML²T⁻²]"}],"answer":2,"solution":"F = ma ⇒ [F] = [M][LT⁻²] = [MLT⁻²]."},{"id":1457,"text":"The work done in moving a charge of 5 C across two points with potential difference 10 V is:","options":[{"label":"A","text":"2 J"},{"label":"B","text":"15 J"},{"label":"C","text":"50 J"},{"label":"D","text":"5 J"}],"answer":2,"solution":"W = QV = 5 × 10 = 50 J."},{"id":1458,"text":"The frequency of a wave with time period 0.02 s is:","options":[{"label":"A","text":"20 Hz"},{"label":"B","text":"50 Hz"},{"label":"C","text":"100 Hz"},{"label":"D","text":"25 Hz"}],"answer":1,"solution":"f = 1/T = 1/0.02 = 50 Hz."},{"id":1459,"text":"The refractive index of a medium is 1.5. Speed of light in this medium is:","options":[{"label":"A","text":"3 × 10⁸ m/s"},{"label":"B","text":"2 × 10⁸ m/s"},{"label":"C","text":"4.5 × 10⁸ m/s"},{"label":"D","text":"1.5 × 10⁸ m/s"}],"answer":1,"solution":"v = c/n = 3×10⁸/1.5 = 2×10⁸ m/s."},{"id":1460,"text":"Which of the following is a scalar quantity?","options":[{"label":"A","text":"Force"},{"label":"B","text":"Velocity"},{"label":"C","text":"Energy"},{"label":"D","text":"Acceleration"}],"answer":2,"solution":"Energy has magnitude only (no direction), hence scalar. Force, velocity, acceleration are vectors."},{"id":1461,"text":"A body of mass 2 kg is moving with velocity 3 m/s. Its kinetic energy is:","options":[{"label":"A","text":"3 J"},{"label":"B","text":"9 J"},{"label":"C","text":"6 J"},{"label":"D","text":"18 J"}],"answer":1,"solution":"KE = ½mv² = ½ × 2 × 9 = 9 J."},{"id":1472,"text":"A convex lens has a focal length of 20 cm. An object is placed at a distance of 30 cm from the lens. What is the nature and position of the image formed?","options":[{"label":"A","text":"Real, inverted, 60 cm from the lens on the opposite side."},{"label":"B","text":"Virtual, erect, 60 cm from the lens on the same side."},{"label":"C","text":"Real, inverted, 30 cm from the lens on the opposite side."},{"label":"D","text":"Virtual, erect, 30 cm from the lens on the same side."}],"answer":0,"solution":"Using the lens formula 1/f = 1/v - 1/u, where f = 20 cm and u = -30 cm (object distance is negative). 1/20 = 1/v - 1/(-30) =&gt; 1/v = 1/20 - 1/30 = (3-2)/60 = 1/60. So, v = 60 cm. Since v is positive, the image is real and formed on the opposite side. The magnification m = v/u = 60/(-30) = -2, indicating an inverted image."},{"id":1473,"text":"The direction of induced current is given by:","options":[{"label":"A","text":"Ampere&#39;s law"},{"label":"B","text":"Biot-Savart law"},{"label":"C","text":"Lenz&#39;s law"},{"label":"D","text":"Ohm&#39;s law"}],"answer":2,"solution":"Lenz&#39;s law determines direction: induced current opposes change in flux."},{"id":1475,"text":"A convex mirror always forms which type of image?","options":[{"label":"A","text":"Real and inverted"},{"label":"B","text":"Virtual and erect"},{"label":"C","text":"Real and erect"},{"label":"D","text":"Virtual and inverted"}],"answer":1,"solution":"Convex mirrors always form virtual, erect, and diminished images regardless of object position."},{"id":1476,"text":"A body of mass 2 kg is moving with velocity 3 m/s. Its kinetic energy is:","options":[{"label":"A","text":"3 J"},{"label":"B","text":"9 J"},{"label":"C","text":"6 J"},{"label":"D","text":"18 J"}],"answer":1,"solution":"KE = ½mv² = ½ × 2 × 9 = 9 J."},{"id":1477,"text":"A wire of length L and area A has resistance R. If length is halved and area doubled, new resistance is:","options":[{"label":"A","text":"R/2"},{"label":"B","text":"R/4"},{"label":"C","text":"R"},{"label":"D","text":"2R"}],"answer":1,"solution":"R&#39; = ρ(L/2)/(2A) = (ρL/A)/4 = R/4."},{"id":1478,"text":"A particle of mass m is released from rest at a height h above a horizontal surface. If it falls under gravity, and experiences a resistive force proportional to its velocity (F_r = -kv), where k is a positive constant, what is the terminal velocity it approaches?","options":[{"label":"A","text":"mg/k"},{"label":"B","text":"√(2gh)"},{"label":"C","text":"k/mg"},{"label":"D","text":"mgh/k"}],"answer":0,"solution":"Terminal velocity is reached when the net force on the particle is zero. The forces acting on the particle are gravity (mg downwards) and the resistive force (-kv upwards). Thus, mg - kv_t = 0, which gives v_t = mg/k."},{"id":1481,"text":"A thin uniform ring of mass M and radius R is rotating about an axis perpendicular to its plane and passing through its center with an angular velocity ω. Two point masses, each of mass m, are gently attached at diametrically opposite points on the ring. The new angular velocity of the system will be:","options":[{"label":"A","text":"Mω / (M + 2m)"},{"label":"B","text":"Mω / (M + m)"},{"label":"C","text":"(M + 2m)ω / M"},{"label":"D","text":"Mω / (M + m/2)"}],"answer":0,"solution":"According to the principle of conservation of angular momentum:Initial angular momentum (L_initial) = I_initial * ωFor the ring, I_initial = MR²So, L_initial = MR²ωWhen two point masses &#39;m&#39; are attached at diametrically opposite points, the new moment of inertia (I_final) will be:I_final = I_ring + I_two_point_masses = MR² + mR² + mR² = (M + 2m)R²Let the new angular velocity be ω&#39;.Final angular momentum (L_final) = I_final * ω&#39; = (M + 2m)R²ω&#39;Equating initial and final angular momentum:MR²ω = (M + 2m)R²ω&#39;ω&#39; = MR²ω / ((M + 2m)R²)ω&#39; = Mω / (M + 2m)"},{"id":1482,"text":"A body starts from rest and moves with uniform acceleration of 2 m/s². The distance covered in 5 seconds is:","options":[{"label":"A","text":"10 m"},{"label":"B","text":"25 m"},{"label":"C","text":"50 m"},{"label":"D","text":"5 m"}],"answer":1,"solution":"s = ut + ½at² = 0 + ½ × 2 × 25 = 25 m."},{"id":1490,"text":"Which of the following has the highest specific heat capacity?","options":[{"label":"A","text":"Iron"},{"label":"B","text":"Copper"},{"label":"C","text":"Water"},{"label":"D","text":"Lead"}],"answer":2,"solution":"Water has the highest specific heat capacity (4200 J/kg°C) among common substances."},{"id":1495,"text":"If the speed of light is 3 × 10⁸ m/s, the distance traveled by light in one year (light year) is approximately:","options":[{"label":"A","text":"9.46 × 10¹² km"},{"label":"B","text":"9.46 × 10¹² km"},{"label":"C","text":"9.46 × 10¹⁵ km"},{"label":"D","text":"3 × 10⁸ km"}],"answer":1,"solution":"1 light year = 9.46 × 10¹² km."},{"id":1497,"text":"The internal resistance of an ideal voltmeter is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"Low"},{"label":"C","text":"Infinity"},{"label":"D","text":"1 Ω"}],"answer":2,"solution":"Ideal voltmeter has infinite resistance to draw zero current."},{"id":1499,"text":"The reason of mirage in desert is:","options":[{"label":"A","text":"Reflection"},{"label":"B","text":"Total internal reflection"},{"label":"C","text":"Diffraction"},{"label":"D","text":"Interference"}],"answer":1,"solution":"Mirage occurs due to total internal reflection of light in layers of different refractive indices."},{"id":1500,"text":"A solid cylinder of mass M and radius R rolls without slipping on a horizontal surface with a linear velocity v. The kinetic energy of the cylinder is:","options":[{"label":"A","text":"(1/2)Mv^2"},{"label":"B","text":"(3/4)Mv^2"},{"label":"C","text":"Mv^2"},{"label":"D","text":"(1/4)Mv^2"}],"answer":1,"solution":"The total kinetic energy (KE_total) of a body rolling without slipping is the sum of its translational kinetic energy (KE_translational) and rotational kinetic energy (KE_rotational).KE_total = KE_translational + KE_rotationalKE_translational = (1/2)Mv^2KE_rotational = (1/2)Iω^2For a solid cylinder, the moment of inertia I = (1/2)MR^2.For rolling without slipping, the linear velocity v and angular velocity ω are related by v = Rω, so ω = v/R.Substituting these into the rotational kinetic energy equation:KE_rotational = (1/2) * ((1/2)MR^2) * (v/R)^2KE_rotational = (1/4)MR^2 * (v^2/R^2)KE_rotational = (1/4)Mv^2Now, sum the translational and rotational kinetic energies:KE_total = (1/2)Mv^2 + (1/4)Mv^2KE_total = (2/4)Mv^2 + (1/4)Mv^2KE_total = (3/4)Mv^2"},{"id":1501,"text":"Which of the following is a scalar quantity?","options":[{"label":"A","text":"Force"},{"label":"B","text":"Velocity"},{"label":"C","text":"Energy"},{"label":"D","text":"Acceleration"}],"answer":2,"solution":"Energy has magnitude only (no direction), hence scalar. Force, velocity, acceleration are vectors."},{"id":1502,"text":"A body of mass 5 kg is moving with momentum 20 kg m/s. Its velocity is:","options":[{"label":"A","text":"2 m/s"},{"label":"B","text":"4 m/s"},{"label":"C","text":"100 m/s"},{"label":"D","text":"0.25 m/s"}],"answer":1,"solution":"v = p/m = 20/5 = 4 m/s."},{"id":1504,"text":"The de Broglie wavelength of an electron accelerated through a potential difference V is given by:","options":[{"label":"A","text":"h / sqrt(mV)"},{"label":"B","text":"h / sqrt(2meV)"},{"label":"C","text":"h / sqrt(2mVe)"},{"label":"D","text":"h / sqrt(V/2me)"}],"answer":1,"solution":"When an electron is accelerated through a potential difference V, it gains kinetic energy KE = eV. The kinetic energy is also given by KE = p^2 / 2m, where p is the momentum and m is the mass of the electron. Therefore, p = sqrt(2mKE) = sqrt(2meV). The de Broglie wavelength is given by  = h/p. Substituting the expression for p, we get  = h / sqrt(2meV)."},{"id":1507,"text":"The coefficient of performance of a refrigerator is given by:","options":[{"label":"A","text":"Q/W"},{"label":"B","text":"Q/W"},{"label":"C","text":"W/Q"},{"label":"D","text":"(Q-Q)/W"}],"answer":1,"solution":"COP = Q/W where Q is heat extracted from cold reservoir and W is work input."},{"id":1509,"text":"The magnetic field at the center of a current carrying circular loop is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"I/2R"},{"label":"C","text":"I/R"},{"label":"D","text":"I/4piR"}],"answer":1,"solution":"B = I/(2R) at center of circular loop."},{"id":1510,"text":"When light of frequency  is incident on a photocathode, the stopping potential is V. When light of frequency  is incident on the same photocathode, the stopping potential is V. If V &gt; V, which of the following relations is correct? (h is Planck&#39;s constant, e is the charge of an electron)","options":[{"label":"A","text":"h( - ) = e(V - V)"},{"label":"B","text":"h( - ) = e(V - V)"},{"label":"C","text":"h( + ) = e(V + V)"},{"label":"D","text":"h( / ) = e(V / V)"}],"answer":0,"solution":"According to Einstein&#39;s photoelectric equation, the maximum kinetic energy of emitted photoelectrons (KE_max) is given by:\r\nh =  + KE_max\r\nwhere h is Planck&#39;s constant,  is the frequency of incident light, and  is the work function of the metal.\r\n\r\nThe stopping potential (V_s) is related to KE_max by: KE_max = eV_s\r\nSo, the equation becomes: h =  + eV_s\r\n\r\nFor the first case:\r\nh =  + eV  (Equation 1)\r\n\r\nFor the second case:\r\nh =  + eV  (Equation 2)\r\n\r\nSubtract Equation 1 from Equation 2:\r\n(h - h) = ( + eV) - ( + eV)\r\nh( - ) = eV - eV\r\nh( - ) = e(V - V)"},{"id":1512,"text":"A particle of mass &#39;m&#39; is projected with velocity &#39;v&#39; at an angle &#39;&#39; with the horizontal. The magnitude of the change in momentum of the particle from the time of projection till it reaches the maximum height is:","options":[{"label":"A","text":"mv cos"},{"label":"B","text":"mv sin"},{"label":"C","text":""},{"label":"D","text":""}],"answer":1,"solution":"At the time of projection, the momentum components are Px = mv cos (horizontal) and Py = mv sin (vertical). At the maximum height, the vertical component of velocity becomes zero, so the vertical component of momentum is zero. The horizontal component of momentum remains mv cos. Change in momentum (P) = Final momentum - Initial momentum. P_x = mv cos - mv cos = 0. P_y = 0 - mv sin = -mv sin. The magnitude of the change in momentum is |P_y| = mv sin."},{"id":1513,"text":"A particle moves in a circle of radius 2 m with speed 4 m/s. Its centripetal acceleration is:","options":[{"label":"A","text":"2 m/s^2"},{"label":"B","text":"8 m/s^2"},{"label":"C","text":"4 m/s^2"},{"label":"D","text":"16 m/s^2"}],"answer":1,"solution":"a_c = v^2/r = 16/2 = 8 m/s^2."},{"id":1514,"text":"The energy equivalent of 1 amu is:","options":[{"label":"A","text":"931 eV"},{"label":"B","text":"931 MeV"},{"label":"C","text":"931 keV"},{"label":"D","text":"931 J"}],"answer":1,"solution":"1 amu = 931.5 MeV/c^2."},{"id":1523,"text":"The internal resistance of an ideal voltmeter is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"Low"},{"label":"C","text":"Infinity"},{"label":"D","text":"1"}],"answer":2,"solution":"Ideal voltmeter has infinite resistance to draw zero current."},{"id":1525,"text":"Which of the following is a scalar quantity?","options":[{"label":"A","text":"Force"},{"label":"B","text":"Velocity"},{"label":"C","text":"Energy"},{"label":"D","text":"Acceleration"}],"answer":2,"solution":"Energy has magnitude only (no direction), hence scalar. Force, velocity, acceleration are vectors."},{"id":1527,"text":"A thin uniform ring of mass M and radius R is rotating about an axis perpendicular to its plane and passing through its center with an angular velocity . Two point masses, each of mass m, are gently attached at diametrically opposite points on the ring. The new angular velocity of the system will be:","options":[{"label":"A","text":"M / (M + 2m)"},{"label":"B","text":"M / (M + m)"},{"label":"C","text":"(M + 2m) / M"},{"label":"D","text":"M / (M + m/2)"}],"answer":0,"solution":"According to the principle of conservation of angular momentum:Initial angular momentum (L_initial) = I_initial * For the ring, I_initial = MR^2So, L_initial = MR^2When two point masses &#39;m&#39; are attached at diametrically opposite points, the new moment of inertia (I_final) will be:I_final = I_ring + I_two_point_masses = MR^2 + mR^2 + mR^2 = (M + 2m)R^2Let the new angular velocity be &#39;.Final angular momentum (L_final) = I_final * &#39; = (M + 2m)R^2&#39;Equating initial and final angular momentum:MR^2 = (M + 2m)R^2&#39;&#39; = MR^2 / ((M + 2m)R^2)&#39; = M / (M + 2m)"},{"id":1528,"text":"The time period of a simple pendulum depends on:","options":[{"label":"A","text":"Mass of bob"},{"label":"B","text":"Amplitude (small)"},{"label":"C","text":"Length of pendulum"},{"label":"D","text":"Material of bob"}],"answer":2,"solution":"T = 2pisqrt(L/g). Time period depends only on length and g."},{"id":1530,"text":"When light of frequency  is incident on a photocathode, the stopping potential is V. When light of frequency  is incident on the same photocathode, the stopping potential is V. If V &gt; V, which of the following relations is correct? (h is Planck&#39;s constant, e is the charge of an electron)","options":[{"label":"A","text":"h( - ) = e(V - V)"},{"label":"B","text":"h( - ) = e(V - V)"},{"label":"C","text":"h( + ) = e(V + V)"},{"label":"D","text":"h( / ) = e(V / V)"}],"answer":0,"solution":"According to Einstein&#39;s photoelectric equation, the maximum kinetic energy of emitted photoelectrons (KE_max) is given by:h =  + KE_maxwhere h is Planck&#39;s constant,  is the frequency of incident light, and  is the work function of the metal.The stopping potential (V_s) is related to KE_max by: KE_max = eV_sSo, the equation becomes: h =  + eV_sFor the first case:h =  + eV  (Equation 1)For the second case:h =  + eV  (Equation 2)Subtract Equation 1 from Equation 2:(h - h) = ( + eV) - ( + eV)h( - ) = eV - eVh( - ) = e(V - V)"},{"id":1531,"text":"A convex mirror always forms which type of image?","options":[{"label":"A","text":"Real and inverted"},{"label":"B","text":"Virtual and erect"},{"label":"C","text":"Real and erect"},{"label":"D","text":"Virtual and inverted"}],"answer":1,"solution":"Convex mirrors always form virtual, erect, and diminished images regardless of object position."},{"id":1535,"text":"The coefficient of performance of a refrigerator is given by:","options":[{"label":"A","text":"Q/W"},{"label":"B","text":"Q/W"},{"label":"C","text":"W/Q"},{"label":"D","text":"(Q-Q)/W"}],"answer":1,"solution":"COP = Q/W where Q is heat extracted from cold reservoir and W is work input."},{"id":1536,"text":"The time period of a simple pendulum depends on:","options":[{"label":"A","text":"Mass of bob"},{"label":"B","text":"Amplitude (small)"},{"label":"C","text":"Length of pendulum"},{"label":"D","text":"Material of bob"}],"answer":2,"solution":"T = 2pisqrt(L/g). Time period depends only on length and g."},{"id":1537,"text":"Which of the following has the highest specific heat capacity?","options":[{"label":"A","text":"Iron"},{"label":"B","text":"Copper"},{"label":"C","text":"Water"},{"label":"D","text":"Lead"}],"answer":2,"solution":"Water has the highest specific heat capacity (4200 J/kg degrees C) among common substances."},{"id":1538,"text":"What is the nature of the force between two parallel current-carrying conductors?","options":[{"label":"A","text":"Repulsive"},{"label":"B","text":"Attractive"},{"label":"C","text":"Both attractive and repulsive"},{"label":"D","text":"Neutral"}],"answer":2,"solution":"The force between two parallel current-carrying conductors can be either attractive or repulsive, depending on the direction of the current flow."},{"id":1543,"text":"The dimensional formula of force is:","options":[{"label":"A","text":"[MLT]"},{"label":"B","text":"[MLT^2]"},{"label":"C","text":"[MLT^2]"},{"label":"D","text":"[ML^2T^2]"}],"answer":2,"solution":"F = ma -&gt; [F] = [M][LT^2] = [MLT^2]."},{"id":1544,"text":"What is the phenomenon where an electric current is generated in a conductor when it is exposed to a changing magnetic field?","options":[{"label":"A","text":"Electromagnetic induction"},{"label":"B","text":"Electrostatic induction"},{"label":"C","text":"Magnetic induction"},{"label":"D","text":"Electric induction"}],"answer":0,"solution":"Electromagnetic induction is the phenomenon where an electric current is generated in a conductor when it is exposed to a changing magnetic field."},{"id":1545,"text":"When light of frequency  is incident on a photocathode, the stopping potential is V. When light of frequency  is incident on the same photocathode, the stopping potential is V. If V &gt; V, which of the following relations is correct? (h is Planck&#39;s constant, e is the charge of an electron)","options":[{"label":"A","text":"h( - ) = e(V - V)"},{"label":"B","text":"h( - ) = e(V - V)"},{"label":"C","text":"h( + ) = e(V + V)"},{"label":"D","text":"h( / ) = e(V / V)"}],"answer":0,"solution":"According to Einstein&#39;s photoelectric equation, the maximum kinetic energy of emitted photoelectrons (KE_max) is given by:h =  + KE_maxwhere h is Planck&#39;s constant,  is the frequency of incident light, and  is the work function of the metal.The stopping potential (V_s) is related to KE_max by: KE_max = eV_sSo, the equation becomes: h =  + eV_sFor the first case:h =  + eV  (Equation 1)For the second case:h =  + eV  (Equation 2)Subtract Equation 1 from Equation 2:(h - h) = ( + eV) - ( + eV)h( - ) = eV - eVh( - ) = e(V - V)"},{"id":1546,"text":"A force of 10 N acts on a body of mass 2 kg for 5 s. The impulse is:","options":[{"label":"A","text":"10 Ns"},{"label":"B","text":"50 Ns"},{"label":"C","text":"2 Ns"},{"label":"D","text":"25 Ns"}],"answer":1,"solution":"Impulse = F x t = 10 x 5 = 50 Ns."},{"id":1549,"text":"The refractive index of a medium is 1.5. Speed of light in this medium is:","options":[{"label":"A","text":"3 x 10 m/s"},{"label":"B","text":"2 x 10 m/s"},{"label":"C","text":"4.5 x 10 m/s"},{"label":"D","text":"1.5 x 10 m/s"}],"answer":1,"solution":"v = c/n = 3x10/1.5 = 2x10 m/s."},{"id":1550,"text":"A particle of mass m is released from rest at a height h above a horizontal surface. If it falls under gravity, and experiences a resistive force proportional to its velocity (F_r = -kv), where k is a positive constant, what is the terminal velocity it approaches?","options":[{"label":"A","text":"mg/k"},{"label":"B","text":"sqrt(2gh)"},{"label":"C","text":"k/mg"},{"label":"D","text":"mgh/k"}],"answer":0,"solution":"Terminal velocity is reached when the net force on the particle is zero. The forces acting on the particle are gravity (mg downwards) and the resistive force (-kv upwards). Thus, mg - kv_t = 0, which gives v_t = mg/k."},{"id":1551,"text":"The dimension of Planck&#39;s constant is same as:","options":[{"label":"A","text":"Energy"},{"label":"B","text":"Angular momentum"},{"label":"C","text":"Force"},{"label":"D","text":"Power"}],"answer":1,"solution":"h = E/ -&gt; [ML^2T] same as angular momentum."},{"id":1556,"text":"A convex lens of focal length 20 cm is placed in contact with a concave lens of focal length 30 cm. The focal length of the combination is:","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""}],"answer":2,"solution":"For a combination of thin lenses in contact, the reciprocal of the equivalent focal length (F) is given by 1/F = 1/f + 1/f. Given f = +20 cm (convex lens) and f = -30 cm (concave lens). So, 1/F = 1/20 + 1/(-30) = 1/20 - 1/30. To combine, find a common denominator, which is 60. 1/F = (3/60) - (2/60) = 1/60. Therefore, F = +60 cm."},{"id":1557,"text":"A lens of power +2 D has focal length:","options":[{"label":"A","text":"0.5 m"},{"label":"B","text":"0.5 m"},{"label":"C","text":"2 m"},{"label":"D","text":"5 m"}],"answer":1,"solution":"f = 1/P = 1/2 = 0.5 m. Positive power -&gt; convex lens."},{"id":1558,"text":"The de Broglie wavelength of an electron accelerated through a potential difference V is given by:","options":[{"label":"A","text":"h / sqrt(mV)"},{"label":"B","text":"h / sqrt(2meV)"},{"label":"C","text":"h / sqrt(2mVe)"},{"label":"D","text":"h / sqrt(V/2me)"}],"answer":1,"solution":"When an electron is accelerated through a potential difference V, it gains kinetic energy KE = eV. The kinetic energy is also given by KE = p^2 / 2m, where p is the momentum and m is the mass of the electron. Therefore, p = sqrt(2mKE) = sqrt(2meV). The de Broglie wavelength is given by  = h/p. Substituting the expression for p, we get  = h / sqrt(2meV)."},{"id":1559,"text":"The energy equivalent of 1 amu is:","options":[{"label":"A","text":"931 eV"},{"label":"B","text":"931 MeV"},{"label":"C","text":"931 keV"},{"label":"D","text":"931 J"}],"answer":1,"solution":"1 amu = 931.5 MeV/c^2."},{"id":1565,"text":"What is the phenomenon where an electric current is generated in a conductor when it is exposed to a changing magnetic field?","options":[{"label":"A","text":"Electromagnetic induction"},{"label":"B","text":"Electrostatic induction"},{"label":"C","text":"Magnetic induction"},{"label":"D","text":"Electric induction"}],"answer":0,"solution":"Electromagnetic induction is the phenomenon where an electric current is generated in a conductor when it is exposed to a changing magnetic field."},{"id":1569,"text":"An electron is accelerated through a potential difference V. If its de Broglie wavelength is , then the de Broglie wavelength of a proton accelerated through the same potential difference V will be: (Given: m_p is the mass of proton, m_e is the mass of electron)","options":[{"label":"A","text":"* sqrt(m_e / m_p)"},{"label":"B","text":"* sqrt(m_p / m_e)"},{"label":"C","text":"* (m_e / m_p)"},{"label":"D","text":"* (m_p / m_e)"}],"answer":0,"solution":"The de Broglie wavelength () is given by  = h/p, where h is Planck&#39;s constant and p is the momentum. When a charged particle (charge q, mass m) is accelerated through a potential difference V, its kinetic energy (KE) is qV.\r\nAlso, KE = p^2 / (2m), so p = sqrt(2mKE) = sqrt(2mqV).\r\nTherefore, the de Broglie wavelength can be written as  = h / sqrt(2mqV).\r\nFor an electron:\r\n_e = h / sqrt(2m_e q_e V) =  (given)\r\nFor a proton:\r\n_p = h / sqrt(2m_p q_p V)\r\nSince the charge of an electron (q_e) and a proton (q_p) are equal in magnitude (let&#39;s denote it as e), and they are accelerated through the same potential V:\r\n_e = h / sqrt(2m_e e V)\r\n_p = h / sqrt(2m_p e V)\r\nNow, let&#39;s find the ratio _p / _e:\r\n_p / _e = [h / sqrt(2m_p e V)] / [h / sqrt(2m_e e V)]\r\n_p / _e = sqrt(2m_e e V) / sqrt(2m_p e V)\r\n_p / _e = sqrt(m_e / m_p)\r\nSo, _p =  * sqrt(m_e / m_p)."},{"id":1570,"text":"A uniform rod of length L and mass M is pivoted at one end. It is released from a horizontal position. What is the angular acceleration of the rod when it is vertical?","options":[{"label":"A","text":"3g/L"},{"label":"B","text":"2g/L"},{"label":"C","text":"3g/2L"},{"label":"D","text":"g/L"}],"answer":2,"solution":"The moment of inertia of a rod about one end is I = (1/3)ML^2. The torque due to gravity when the rod is vertical is  = Mg(L/2). Using Newton&#39;s second law for rotation,  = I, we get Mg(L/2) = (1/3)ML^2. Solving for , we get  = 3g/2L."},{"id":1573,"text":"A convex lens has a focal length of 20 cm. An object is placed at a distance of 30 cm from the lens. What is the nature and position of the image formed?","options":[{"label":"A","text":"Real, inverted, 60 cm from the lens on the opposite side."},{"label":"B","text":"Virtual, erect, 60 cm from the lens on the same side."},{"label":"C","text":"Real, inverted, 30 cm from the lens on the opposite side."},{"label":"D","text":"Virtual, erect, 30 cm from the lens on the same side."}],"answer":0,"solution":"Using the lens formula 1/f = 1/v - 1/u, where f = 20 cm and u = -30 cm (object distance is negative). 1/20 = 1/v - 1/(-30) =&gt; 1/v = 1/20 - 1/30 = (3-2)/60 = 1/60. So, v = 60 cm. Since v is positive, the image is real and formed on the opposite side. The magnification m = v/u = 60/(-30) = -2, indicating an inverted image."},{"id":1576,"text":"The direction of induced current is given by:","options":[{"label":"A","text":"Ampere&#39;s law"},{"label":"B","text":"Biot-Savart law"},{"label":"C","text":"Lenz&#39;s law"},{"label":"D","text":"Ohm&#39;s law"}],"answer":2,"solution":"Lenz&#39;s law determines direction: induced current opposes change in flux."},{"id":1579,"text":"What is the nature of the force between two parallel current-carrying conductors?","options":[{"label":"A","text":"Repulsive"},{"label":"B","text":"Attractive"},{"label":"C","text":"Both attractive and repulsive"},{"label":"D","text":"Neutral"}],"answer":2,"solution":"The force between two parallel current-carrying conductors can be either attractive or repulsive, depending on the direction of the current flow."},{"id":1580,"text":"The coefficient of performance of a refrigerator is given by:","options":[{"label":"A","text":"Q/W"},{"label":"B","text":"Q/W"},{"label":"C","text":"W/Q"},{"label":"D","text":"(Q-Q)/W"}],"answer":1,"solution":"COP = Q/W where Q is heat extracted from cold reservoir and W is work input."},{"id":1585,"text":"A solid cylinder of mass M and radius R rolls without slipping on a horizontal surface with a linear velocity v. The kinetic energy of the cylinder is:","options":[{"label":"A","text":"(1/2)Mv^2"},{"label":"B","text":"(3/4)Mv^2"},{"label":"C","text":"Mv^2"},{"label":"D","text":"(1/4)Mv^2"}],"answer":1,"solution":"The total kinetic energy (KE_total) of a body rolling without slipping is the sum of its translational kinetic energy (KE_translational) and rotational kinetic energy (KE_rotational).\r\nKE_total = KE_translational + KE_rotational\r\nKE_translational = (1/2)Mv^2\r\nKE_rotational = (1/2)I^2\r\nFor a solid cylinder, the moment of inertia I = (1/2)MR^2.\r\nFor rolling without slipping, the linear velocity v and angular velocity  are related by v = R, so  = v/R.\r\nSubstituting these into the rotational kinetic energy equation:\r\nKE_rotational = (1/2) * ((1/2)MR^2) * (v/R)^2\r\nKE_rotational = (1/4)MR^2 * (v^2/R^2)\r\nKE_rotational = (1/4)Mv^2\r\nNow, sum the translational and rotational kinetic energies:\r\nKE_total = (1/2)Mv^2 + (1/4)Mv^2\r\nKE_total = (2/4)Mv^2 + (1/4)Mv^2\r\nKE_total = (3/4)Mv^2"},{"id":1587,"text":"A body of mass 5 kg is moving with momentum 20 kg m/s. Its velocity is:","options":[{"label":"A","text":"2 m/s"},{"label":"B","text":"4 m/s"},{"label":"C","text":"100 m/s"},{"label":"D","text":"0.25 m/s"}],"answer":1,"solution":"v = p/m = 20/5 = 4 m/s."},{"id":1594,"text":"What is the unit of measurement for entropy?","options":[{"label":"A","text":"Joule"},{"label":"B","text":"Joule per Kelvin"},{"label":"C","text":"Kelvin"},{"label":"D","text":"Newton"}],"answer":1,"solution":"Entropy is measured in units of Joule per Kelvin (J/K)."},{"id":1595,"text":"The reason of mirage in desert is:","options":[{"label":"A","text":"Reflection"},{"label":"B","text":"Total internal reflection"},{"label":"C","text":"Diffraction"},{"label":"D","text":"Interference"}],"answer":1,"solution":"Mirage occurs due to total internal reflection of light in layers of different refractive indices."},{"id":1599,"text":"A wire of length L and area A has resistance R. If length is halved and area doubled, new resistance is:","options":[{"label":"A","text":"R/2"},{"label":"B","text":"R/4"},{"label":"C","text":"R"},{"label":"D","text":"2R"}],"answer":1,"solution":"R&#39; = (L/2)/(2A) = (L/A)/4 = R/4."},{"id":1600,"text":"The work done in moving a charge of 5 C across two points with potential difference 10 V is:","options":[{"label":"A","text":"2 J"},{"label":"B","text":"15 J"},{"label":"C","text":"50 J"},{"label":"D","text":"5 J"}],"answer":2,"solution":"W = QV = 5 x 10 = 50 J."},{"id":1603,"text":"Which of the following has the highest specific heat capacity?","options":[{"label":"A","text":"Iron"},{"label":"B","text":"Copper"},{"label":"C","text":"Water"},{"label":"D","text":"Lead"}],"answer":2,"solution":"Water has the highest specific heat capacity (4200 J/kg degrees C) among common substances."},{"id":1605,"text":"When light of frequency  is incident on a photocathode, the stopping potential is V. When light of frequency  is incident on the same photocathode, the stopping potential is V. If V &gt; V, which of the following relations is correct? (h is Planck&#39;s constant, e is the charge of an electron)","options":[{"label":"A","text":"h( - ) = e(V - V)"},{"label":"B","text":"h( - ) = e(V - V)"},{"label":"C","text":"h( + ) = e(V + V)"},{"label":"D","text":"h( / ) = e(V / V)"}],"answer":0,"solution":"According to Einstein&#39;s photoelectric equation, the maximum kinetic energy of emitted photoelectrons (KE_max) is given by:\r\nh =  + KE_max\r\nwhere h is Planck&#39;s constant,  is the frequency of incident light, and  is the work function of the metal.\r\n\r\nThe stopping potential (V_s) is related to KE_max by: KE_max = eV_s\r\nSo, the equation becomes: h =  + eV_s\r\n\r\nFor the first case:\r\nh =  + eV  (Equation 1)\r\n\r\nFor the second case:\r\nh =  + eV  (Equation 2)\r\n\r\nSubtract Equation 1 from Equation 2:\r\n(h - h) = ( + eV) - ( + eV)\r\nh( - ) = eV - eV\r\nh( - ) = e(V - V)"},{"id":1607,"text":"A particle of mass &#39;m&#39; is projected with velocity &#39;v&#39; at an angle &#39;&#39; with the horizontal. The magnitude of the change in momentum of the particle from the time of projection till it reaches the maximum height is:","options":[{"label":"A","text":"mv cos"},{"label":"B","text":"mv sin"},{"label":"C","text":""},{"label":"D","text":""}],"answer":1,"solution":"At the time of projection, the momentum components are Px = mv cos (horizontal) and Py = mv sin (vertical). At the maximum height, the vertical component of velocity becomes zero, so the vertical component of momentum is zero. The horizontal component of momentum remains mv cos. Change in momentum (P) = Final momentum - Initial momentum. P_x = mv cos - mv cos = 0. P_y = 0 - mv sin = -mv sin. The magnitude of the change in momentum is |P_y| = mv sin."},{"id":1609,"text":"The dimensional formula of force is:","options":[{"label":"A","text":"[MLT]"},{"label":"B","text":"[MLT^2]"},{"label":"C","text":"[MLT^2]"},{"label":"D","text":"[ML^2T^2]"}],"answer":2,"solution":"F = ma -&gt; [F] = [M][LT^2] = [MLT^2]."},{"id":1614,"text":"The SI unit of electric potential is:","options":[{"label":"A","text":"Coulomb"},{"label":"B","text":"Ohm"},{"label":"C","text":"Volt"},{"label":"D","text":"Ampere"}],"answer":2,"solution":"Electric potential is measured in Volts (V = J/C)."},{"id":1615,"text":"What is the phenomenon where an electric current generates a magnetic field?","options":[{"label":"A","text":"Electromagnetic induction"},{"label":"B","text":"Magnetic induction"},{"label":"C","text":"Ampere&#39;s law"},{"label":"D","text":"Faraday&#39;s law"}],"answer":2,"solution":"Ampere&#39;s law states that an electric current generates a magnetic field, and the direction of the magnetic field can be determined by the right-hand rule."},{"id":1620,"text":"Which law states that entropy of an isolated system always increases?","options":[{"label":"A","text":"First law"},{"label":"B","text":"Second law"},{"label":"C","text":"Third law"},{"label":"D","text":"Zeroth law"}],"answer":1,"solution":"Second law: entropy of isolated system always increases (S  0)."},{"id":1621,"text":"A thin uniform ring of mass M and radius R is rotating about an axis perpendicular to its plane and passing through its center with an angular velocity . Two point masses, each of mass m, are gently attached at diametrically opposite points on the ring. The new angular velocity of the system will be:","options":[{"label":"A","text":"M / (M + 2m)"},{"label":"B","text":"M / (M + m)"},{"label":"C","text":"(M + 2m) / M"},{"label":"D","text":"M / (M + m/2)"}],"answer":0,"solution":"According to the principle of conservation of angular momentum:\r\nInitial angular momentum (L_initial) = I_initial * \r\nFor the ring, I_initial = MR^2\r\nSo, L_initial = MR^2\r\n\r\nWhen two point masses &#39;m&#39; are attached at diametrically opposite points, the new moment of inertia (I_final) will be:\r\nI_final = I_ring + I_two_point_masses = MR^2 + mR^2 + mR^2 = (M + 2m)R^2\r\n\r\nLet the new angular velocity be &#39;.\r\nFinal angular momentum (L_final) = I_final * &#39; = (M + 2m)R^2&#39;\r\n\r\nEquating initial and final angular momentum:\r\nMR^2 = (M + 2m)R^2&#39;\r\n&#39; = MR^2 / ((M + 2m)R^2)\r\n&#39; = M / (M + 2m)"},{"id":1624,"text":"A wire of length L and area A has resistance R. If length is halved and area doubled, new resistance is:","options":[{"label":"A","text":"R/2"},{"label":"B","text":"R/4"},{"label":"C","text":"R"},{"label":"D","text":"2R"}],"answer":1,"solution":"R&#39; = (L/2)/(2A) = (L/A)/4 = R/4."},{"id":1627,"text":"A convex mirror always forms which type of image?","options":[{"label":"A","text":"Real and inverted"},{"label":"B","text":"Virtual and erect"},{"label":"C","text":"Real and erect"},{"label":"D","text":"Virtual and inverted"}],"answer":1,"solution":"Convex mirrors always form virtual, erect, and diminished images regardless of object position."},{"id":1628,"text":"What is the phenomenon where the frequency of a wave appears to change when the source and observer are moving relative to each other?","options":[{"label":"A","text":"Diffraction"},{"label":"B","text":"Refraction"},{"label":"C","text":"Interference"},{"label":"D","text":"Doppler effect"}],"answer":3,"solution":"The Doppler effect is the phenomenon where the frequency of a wave appears to change when the source and observer are moving relative to each other. This effect is commonly observed in sound waves and light waves."},{"id":1634,"text":"A convex lens has a focal length of 20 cm. An object is placed at a distance of 30 cm from the lens. What is the nature and position of the image formed?","options":[{"label":"A","text":"Real, inverted, 60 cm from the lens on the opposite side."},{"label":"B","text":"Virtual, erect, 60 cm from the lens on the same side."},{"label":"C","text":"Real, inverted, 30 cm from the lens on the opposite side."},{"label":"D","text":"Virtual, erect, 30 cm from the lens on the same side."}],"answer":0,"solution":"Using the lens formula 1/f = 1/v - 1/u, where f = 20 cm and u = -30 cm (object distance is negative). 1/20 = 1/v - 1/(-30) =&gt; 1/v = 1/20 - 1/30 = (3-2)/60 = 1/60. So, v = 60 cm. Since v is positive, the image is real and formed on the opposite side. The magnification m = v/u = 60/(-30) = -2, indicating an inverted image."},{"id":1637,"text":"What is the term for the ability of a material to conduct heat?","options":[{"label":"A","text":"Thermal conductivity"},{"label":"B","text":"Thermal resistance"},{"label":"C","text":"Specific heat capacity"},{"label":"D","text":"Thermal energy"}],"answer":0,"solution":"Thermal conductivity is the ability of a material to conduct heat. It is measured in units of watts per meter per kelvin (W/mK) and is an important property of materials in various engineering applications."},{"id":1641,"text":"What is the phenomenon where an electric current generates a magnetic field?","options":[{"label":"A","text":"Electromagnetic induction"},{"label":"B","text":"Magnetic induction"},{"label":"C","text":"Ampere&#39;s law"},{"label":"D","text":"Faraday&#39;s law"}],"answer":2,"solution":"Ampere&#39;s law states that an electric current generates a magnetic field, and the direction of the magnetic field can be determined by the right-hand rule."},{"id":1643,"text":"The SI unit of electric potential is:","options":[{"label":"A","text":"Coulomb"},{"label":"B","text":"Ohm"},{"label":"C","text":"Volt"},{"label":"D","text":"Ampere"}],"answer":2,"solution":"Electric potential is measured in Volts (V = J/C)."},{"id":1649,"text":"The threshold frequency for a metal is 5 x 10 Hz. Its work function is (h = 6.63 x 10 Js):","options":[{"label":"A","text":"3.315 x 10 J"},{"label":"B","text":"3.315 x 10 J"},{"label":"C","text":"6.63 x 10 J"},{"label":"D","text":"1.99 x 10 J"}],"answer":1,"solution":"= hf = 6.63x10 x 5x10 = 3.315x10 J."},{"id":1650,"text":"A solid cylinder of mass M and radius R rolls without slipping on a horizontal surface with a linear velocity v. The kinetic energy of the cylinder is:","options":[{"label":"A","text":"(1/2)Mv^2"},{"label":"B","text":"(3/4)Mv^2"},{"label":"C","text":"Mv^2"},{"label":"D","text":"(1/4)Mv^2"}],"answer":1,"solution":"The total kinetic energy (KE_total) of a body rolling without slipping is the sum of its translational kinetic energy (KE_translational) and rotational kinetic energy (KE_rotational).\r\nKE_total = KE_translational + KE_rotational\r\nKE_translational = (1/2)Mv^2\r\nKE_rotational = (1/2)I^2\r\nFor a solid cylinder, the moment of inertia I = (1/2)MR^2.\r\nFor rolling without slipping, the linear velocity v and angular velocity  are related by v = R, so  = v/R.\r\nSubstituting these into the rotational kinetic energy equation:\r\nKE_rotational = (1/2) * ((1/2)MR^2) * (v/R)^2\r\nKE_rotational = (1/4)MR^2 * (v^2/R^2)\r\nKE_rotational = (1/4)Mv^2\r\nNow, sum the translational and rotational kinetic energies:\r\nKE_total = (1/2)Mv^2 + (1/4)Mv^2\r\nKE_total = (2/4)Mv^2 + (1/4)Mv^2\r\nKE_total = (3/4)Mv^2"}]},{"name":"Chemistry","count":87,"questions":[{"id":1392,"text":"Which quantum number determines the shape of orbital?","options":[{"label":"A","text":"n"},{"label":"B","text":"l"},{"label":"C","text":"m"},{"label":"D","text":"s"}],"answer":1,"solution":"Azimuthal quantum number (l) determines orbital shape (s=0, p=1, d=2)."},{"id":1393,"text":"The most stable allotrope of carbon is:","options":[{"label":"A","text":"Diamond"},{"label":"B","text":"Graphite"},{"label":"C","text":"Fullerene"},{"label":"D","text":"Coal"}],"answer":1,"solution":"Graphite is the most stable allotrope of carbon at room temperature."},{"id":1394,"text":"Which of these is an example of an aromatic compound?","options":[{"label":"A","text":"Cyclohexane"},{"label":"B","text":"Benzene"},{"label":"C","text":"Cyclohexene"},{"label":"D","text":"1,3-cyclohexadiene"}],"answer":1,"solution":"Benzene (C6H6) is aromatic with delocalized 6p electrons."},{"id":1395,"text":"The process of electrolysis is based on:","options":[{"label":"A","text":"Chemical effect of current"},{"label":"B","text":"Magnetic effect of current"},{"label":"C","text":"Redox reactions"},{"label":"D","text":"Heating effect"}],"answer":2,"solution":"Electrolysis involves redox reactions at electrodes driven by electric current."},{"id":1396,"text":"Which of the following is a saturated hydrocarbon?","options":[{"label":"A","text":"C2H4"},{"label":"B","text":"C3H8"},{"label":"C","text":"C2H2"},{"label":"D","text":"C6H6"}],"answer":1,"solution":"Propane (C3H8) follows CₙH₂ₙ₊₂ → saturated alkane."},{"id":1397,"text":"The oxide that turns red litmus blue is:","options":[{"label":"A","text":"CO2"},{"label":"B","text":"SO2"},{"label":"C","text":"Na2O"},{"label":"D","text":"P2O5"}],"answer":2,"solution":"Na2O is basic oxide → turns red litmus blue. CO2, SO2, P2O5 are acidic."},{"id":1398,"text":"The number of atoms in 1 mole of any substance is:","options":[{"label":"A","text":"6.022 × 10²³"},{"label":"B","text":"Avogadro's number"},{"label":"C","text":"6.022 × 10²³"},{"label":"D","text":"Both A and B"}],"answer":1,"solution":"1 mole = 6.022 × 10²³ particles = Avogadro's number."},{"id":1399,"text":"Which of these is a greenhouse gas?","options":[{"label":"A","text":"N2"},{"label":"B","text":"O2"},{"label":"C","text":"CH4"},{"label":"D","text":"H2"}],"answer":2,"solution":"Methane (CH4) is a potent greenhouse gas (~25× more effective than CO2)."},{"id":1400,"text":"Which of the following has covalent bonding?","options":[{"label":"A","text":"NaCl"},{"label":"B","text":"H2O"},{"label":"C","text":"KBr"},{"label":"D","text":"CaO"}],"answer":1,"solution":"H2O has covalent bonds (sharing of electrons). NaCl, KBr, CaO are ionic."},{"id":1401,"text":"pH scale ranges from:","options":[{"label":"A","text":"0 to 7"},{"label":"B","text":"7 to 14"},{"label":"C","text":"0 to 14"},{"label":"D","text":"1 to 10"}],"answer":2,"solution":"pH scale ranges 0-14 (0-6 acidic, 7 neutral, 8-14 basic)."},{"id":1422,"text":"The element with electronic configuration 1s²2s²2p63s²3p6 belongs to:","options":[{"label":"A","text":"Group 2"},{"label":"B","text":"Group 18"},{"label":"C","text":"Group 16"},{"label":"D","text":"Group 17"}],"answer":1,"solution":"Full 3p6 → noble gas configuration → Group 18 (Argon)."},{"id":1423,"text":"Which of the following shows paramagnetism?","options":[{"label":"A","text":"H2"},{"label":"B","text":"N2"},{"label":"C","text":"O2"},{"label":"D","text":"F2"}],"answer":2,"solution":"O2 has two unpaired electrons in its MO configuration → paramagnetic."},{"id":1424,"text":"The IUPAC name of CH3COOH is:","options":[{"label":"A","text":"Formic acid"},{"label":"B","text":"Ethanoic acid"},{"label":"C","text":"Acetic acid"},{"label":"D","text":"Methanoic acid"}],"answer":1,"solution":"CH3COOH → 2 carbons → Ethanoic acid (common: acetic acid)."},{"id":1425,"text":"The shape of NH3 molecule is:","options":[{"label":"A","text":"Trigonal planar"},{"label":"B","text":"Trigonal pyramidal"},{"label":"C","text":"Tetrahedral"},{"label":"D","text":"Linear"}],"answer":1,"solution":"NH3: 3 bond pairs + 1 lone pair → trigonal pyramidal shape."},{"id":1426,"text":"Which of the following is NOT a polymer?","options":[{"label":"A","text":"Nylon"},{"label":"B","text":"Cellulose"},{"label":"C","text":"Glucose"},{"label":"D","text":"PVC"}],"answer":2,"solution":"Glucose is a monomer (monosaccharide), not a polymer. Nylon, cellulose, PVC are polymers."},{"id":1427,"text":"In a redox reaction, oxidation involves:","options":[{"label":"A","text":"Loss of electrons"},{"label":"B","text":"Gain of electrons"},{"label":"C","text":"Gain of hydrogen"},{"label":"D","text":"Loss of oxygen"}],"answer":0,"solution":"Oxidation = loss of electrons, Reduction = gain of electrons (OIL RIG)."},{"id":1428,"text":"The bond angle in water is approximately:","options":[{"label":"A","text":"90°"},{"label":"B","text":"109.5°"},{"label":"C","text":"104.5°"},{"label":"D","text":"120°"}],"answer":2,"solution":"Water has bent shape with 104.5° angle due to lone pair repulsion."},{"id":1429,"text":"Which of these is a double displacement reaction?","options":[{"label":"A","text":"2H2 + O2 → 2H2O"},{"label":"B","text":"NaCl + AgNO3 → AgCl + NaNO3"},{"label":"C","text":"Zn + H2SO4 → ZnSO4 + H2"},{"label":"D","text":"CaCO3 → CaO + CO2"}],"answer":1,"solution":"Double displacement: two compounds exchange ions → new compounds."},{"id":1430,"text":"The number of moles in 11 g of CO2 is:","options":[{"label":"A","text":"0.5"},{"label":"B","text":"0.25"},{"label":"C","text":"1"},{"label":"D","text":"2"}],"answer":1,"solution":"Molar mass CO2 = 44 g/mol. n = 11/44 = 0.25."},{"id":1431,"text":"The catalyst used in the contact process for H2SO4 is:","options":[{"label":"A","text":"V2O5"},{"label":"B","text":"Fe"},{"label":"C","text":"Ni"},{"label":"D","text":"Pt"}],"answer":0,"solution":"Contact process uses V2O5 (vanadium pentoxide) as catalyst."},{"id":1447,"text":"The most electronegative element is:","options":[{"label":"A","text":"Oxygen"},{"label":"B","text":"Fluorine"},{"label":"C","text":"Chlorine"},{"label":"D","text":"Nitrogen"}],"answer":1,"solution":"Fluorine (4.0) is the most electronegative element on the Pauling scale."},{"id":1448,"text":"Which gas is produced when zinc reacts with dilute H2SO4?","options":[{"label":"A","text":"Oxygen"},{"label":"B","text":"Chlorine"},{"label":"C","text":"Hydrogen"},{"label":"D","text":"Carbon dioxide"}],"answer":2,"solution":"Zn + H2SO4 → ZnSO4 + H2↑. Hydrogen gas is produced."},{"id":1449,"text":"Which of the following is a noble gas?","options":[{"label":"A","text":"Hydrogen"},{"label":"B","text":"Nitrogen"},{"label":"C","text":"Argon"},{"label":"D","text":"Chlorine"}],"answer":2,"solution":"Argon (Ar) is a noble gas in Group 18 with a full valence shell."},{"id":1450,"text":"The number of oxygen atoms in 1 mole of H2SO4 is:","options":[{"label":"A","text":"4 × 6.022 × 10²³"},{"label":"B","text":"6.022 × 10²³"},{"label":"C","text":"2 × 6.022 × 10²³"},{"label":"D","text":"7 × 6.022 × 10²³"}],"answer":0,"solution":"1 molecule of H2SO4 has 4 O atoms. 1 mole has 4 × NA = 4 × 6.022 × 10²³ atoms."},{"id":1451,"text":"Which bond is present in NaCl?","options":[{"label":"A","text":"Covalent bond"},{"label":"B","text":"Metallic bond"},{"label":"C","text":"Ionic bond"},{"label":"D","text":"Hydrogen bond"}],"answer":2,"solution":"NaCl forms an ionic bond between Na⁺ and Cl⁻ through electron transfer."},{"id":1462,"text":"The pH of a neutral solution at 25°C is:","options":[{"label":"A","text":"0"},{"label":"B","text":"7"},{"label":"C","text":"14"},{"label":"D","text":"1"}],"answer":1,"solution":"[H⁺] = [OH⁻] = 10⁻⁷ M ⇒ pH = 7 at 25°C."},{"id":1463,"text":"The chemical formula of rust is:","options":[{"label":"A","text":"FeO"},{"label":"B","text":"Fe2O3"},{"label":"C","text":"Fe2O3·xH2O"},{"label":"D","text":"Fe3O4"}],"answer":2,"solution":"Rust is hydrated iron(III) oxide, Fe2O3·xH2O."},{"id":1464,"text":"Which catalyst is used in the Haber process for ammonia synthesis?","options":[{"label":"A","text":"Vanadium pentoxide"},{"label":"B","text":"Iron"},{"label":"C","text":"Nickel"},{"label":"D","text":"Platinum"}],"answer":1,"solution":"Haber process uses finely divided iron with promoters (K2O, Al2O3) as catalyst."},{"id":1465,"text":"Which of the following is an isotope of hydrogen?","options":[{"label":"A","text":"Protium"},{"label":"B","text":"Deuterium"},{"label":"C","text":"Tritium"},{"label":"D","text":"All of these"}],"answer":3,"solution":"Protium (¹H), Deuterium (²H), and Tritium (³H) are all isotopes of hydrogen."},{"id":1466,"text":"The number of electrons in Na? ion is:","options":[{"label":"A","text":"11"},{"label":"B","text":"10"},{"label":"C","text":"12"},{"label":"D","text":"9"}],"answer":1,"solution":"Na (11 e⁻) → Na⁺ loses 1 e⁻ → 10 electrons."},{"id":1479,"text":"Which of these is a double displacement reaction?","options":[{"label":"A","text":"2H₂ + O₂ → 2H₂O"},{"label":"B","text":"NaCl + AgNO₃ → AgCl + NaNO₃"},{"label":"C","text":"Zn + H₂SO₄ → ZnSO₄ + H₂"},{"label":"D","text":"CaCO₃ → CaO + CO₂"}],"answer":1,"solution":"Double displacement: two compounds exchange ions → new compounds."},{"id":1484,"text":"The correct order of increasing acidic strength for the following compounds is:","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""}],"answer":1,"solution":"Ethanol is a very weak acid. Phenol is more acidic than ethanol due to resonance stabilization of the phenoxide ion. Acetic acid is a carboxylic acid, much stronger than phenol. Chloroacetic acid is more acidic than acetic acid due to the electron-withdrawing inductive effect (-I effect) of the chlorine atom, which stabilizes the carboxylate anion further. Therefore, the order is Ethanol &lt; Phenol &lt; Acetic acid &lt; Chloroacetic acid."},{"id":1485,"text":"Which of the following is a saturated hydrocarbon?","options":[{"label":"A","text":"C₂H₄"},{"label":"B","text":"C₃H₈"},{"label":"C","text":"C₂H₂"},{"label":"D","text":"C₆H₆"}],"answer":1,"solution":"Propane (C₃H₈) follows CₙH₂ₙ₊₂ → saturated alkane."},{"id":1486,"text":"Which of the following is NOT a polymer?","options":[{"label":"A","text":"Nylon"},{"label":"B","text":"Cellulose"},{"label":"C","text":"Glucose"},{"label":"D","text":"PVC"}],"answer":2,"solution":"Glucose is a monomer (monosaccharide), not a polymer. Nylon, cellulose, PVC are polymers."},{"id":1487,"text":"Which of the following reagents would distinguish between ethanal and propanone?","options":[{"label":"A","text":"Tollen&#39;s reagent"},{"label":"B","text":"Fehling&#39;s solution"},{"label":"C","text":"Benedict&#39;s solution"},{"label":"D","text":"All of the above"}],"answer":3,"solution":"Ethanal (CH3CHO) is an aldehyde, while propanone (CH3COCH3) is a ketone. Aldehydes can be easily oxidized to carboxylic acids by mild oxidizing agents, whereas ketones are generally resistant to oxidation by mild agents. Tollen&#39;s reagent (ammoniacal silver nitrate), Fehling&#39;s solution (alkaline solution of CuSO4 and sodium potassium tartrate), and Benedict&#39;s solution (alkaline solution of CuSO4 and sodium citrate) are all mild oxidizing agents used to detect aldehydes.Ethanal, being an aldehyde, will give a positive test with Tollen&#39;s reagent (forming a silver mirror), Fehling&#39;s solution (forming a red precipitate of Cu2O), and Benedict&#39;s solution (forming a red precipitate of Cu2O).Propanone, being a ketone, will not react with any of these mild oxidizing agents.Therefore, all the listed reagents can distinguish between ethanal and propanone."},{"id":1488,"text":"Which catalyst is used in the Haber process for ammonia synthesis?","options":[{"label":"A","text":"Vanadium pentoxide"},{"label":"B","text":"Iron"},{"label":"C","text":"Nickel"},{"label":"D","text":"Platinum"}],"answer":1,"solution":"Haber process uses finely divided iron with promoters (K₂O, Al₂O₃) as catalyst."},{"id":1491,"text":"Which of the following is a noble gas?","options":[{"label":"A","text":"Hydrogen"},{"label":"B","text":"Nitrogen"},{"label":"C","text":"Argon"},{"label":"D","text":"Chlorine"}],"answer":2,"solution":"Argon (Ar) is a noble gas in Group 18 with a full valence shell."},{"id":1493,"text":"Which of these is a greenhouse gas?","options":[{"label":"A","text":"N₂"},{"label":"B","text":"O₂"},{"label":"C","text":"CH₄"},{"label":"D","text":"H₂"}],"answer":2,"solution":"Methane (CH₄) is a potent greenhouse gas (~25× more effective than CO₂)."},{"id":1496,"text":"The most stable allotrope of carbon is:","options":[{"label":"A","text":"Diamond"},{"label":"B","text":"Graphite"},{"label":"C","text":"Fullerene"},{"label":"D","text":"Coal"}],"answer":1,"solution":"Graphite is the most stable allotrope of carbon at room temperature."},{"id":1498,"text":"Which of the following shows paramagnetism?","options":[{"label":"A","text":"H₂"},{"label":"B","text":"N₂"},{"label":"C","text":"O₂"},{"label":"D","text":"F₂"}],"answer":2,"solution":"O₂ has two unpaired electrons in its MO configuration → paramagnetic."},{"id":1505,"text":"Which of the following reactions will NOT yield an alkyl halide?","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""}],"answer":3,"solution":"Reaction A (Lucas test) yields CHCHCl. Reaction B (free radical halogenation) yields CHCH(Cl)CH and CHCHCHCl. Reaction C (hydrohalogenation of propene, Markovnikov&#39;s rule) yields CHCH(Br)CH. Reaction D (reaction of carboxylic acid with PCl) yields an acyl chloride (CHCHCOCl), not an alkyl halide."},{"id":1508,"text":"The IUPAC name of CHCOOH is:","options":[{"label":"A","text":"Formic acid"},{"label":"B","text":"Ethanoic acid"},{"label":"C","text":"Acetic acid"},{"label":"D","text":"Methanoic acid"}],"answer":1,"solution":"CHCOOH -&gt; 2 carbons -&gt; Ethanoic acid (common: acetic acid)."},{"id":1511,"text":"The element with electronic configuration 1s^22s^22p3s^23p belongs to:","options":[{"label":"A","text":"Group 2"},{"label":"B","text":"Group 18"},{"label":"C","text":"Group 16"},{"label":"D","text":"Group 17"}],"answer":1,"solution":"Full 3p -&gt; noble gas configuration -&gt; Group 18 (Argon)."},{"id":1516,"text":"The number of electrons in Na ion is:","options":[{"label":"A","text":"11"},{"label":"B","text":"10"},{"label":"C","text":"12"},{"label":"D","text":"9"}],"answer":1,"solution":"Na (11 e) -&gt; Na loses 1 e -&gt; 10 electrons."},{"id":1519,"text":"For the reaction N2(g) + 3H2(g) = 2NH3(g), the partial pressures at a given instant are P(N2) = 0.2 atm, P(H2) = 0.1 atm and P(NH3) = 0.02 atm. What is the reaction quotient Qp at that instant?","options":[{"label":"A","text":"0.25 atm^-2"},{"label":"B","text":"2.0 atm^-2"},{"label":"C","text":"10.0 atm^-2"},{"label":"D","text":"0.05 atm^-2"}],"answer":1,"solution":"Qp = P(NH3)^2 / [P(N2) x P(H2)^3] = (0.02)^2 / (0.2 x 0.1^3) = 0.0004 / 0.0002 = 2.0 atm^-2. Option B is correct."},{"id":1520,"text":"The pH of a neutral solution at 25 degrees C is:","options":[{"label":"A","text":"0"},{"label":"B","text":"7"},{"label":"C","text":"14"},{"label":"D","text":"1"}],"answer":1,"solution":"[H] = [OH] = 10 M -&gt; pH = 7 at 25 degrees C."},{"id":1521,"text":"In a redox reaction, oxidation involves:","options":[{"label":"A","text":"Loss of electrons"},{"label":"B","text":"Gain of electrons"},{"label":"C","text":"Gain of hydrogen"},{"label":"D","text":"Loss of oxygen"}],"answer":0,"solution":"Oxidation = loss of electrons, Reduction = gain of electrons (OIL RIG)."},{"id":1522,"text":"The IUPAC name of CH3COCH2COCH3 is:","options":[{"label":"A","text":"Pentane-2,4-dione"},{"label":"B","text":"2,4-Pentanedione"},{"label":"C","text":"Pentane-3-one"},{"label":"D","text":"2,4-Dioxopentane"}],"answer":0,"solution":"The given compound is a diketone. The longest carbon chain containing the two carbonyl groups has five carbons, so the parent alkane is pentane. The carbonyl groups are at positions 2 and 4. Therefore, the IUPAC name is Pentane-2,4-dione. The numbering starts from the end that gives the lower locants to the functional groups."},{"id":1526,"text":"Which gas is produced when zinc reacts with dilute HSO?","options":[{"label":"A","text":"Oxygen"},{"label":"B","text":"Chlorine"},{"label":"C","text":"Hydrogen"},{"label":"D","text":"Carbon dioxide"}],"answer":2,"solution":"Zn + HSO -&gt; ZnSO + H-&gt;. Hydrogen gas is produced."},{"id":1534,"text":"What is the type of reaction that involves the loss of electrons by a species?","options":[{"label":"A","text":"Oxidation reaction"},{"label":"B","text":"Reduction reaction"},{"label":"C","text":"Acid-base reaction"},{"label":"D","text":"Neutralization reaction"}],"answer":0,"solution":"An oxidation reaction is a type of reaction that involves the loss of electrons by a species."},{"id":1540,"text":"Which quantum number determines the shape of orbital?","options":[{"label":"A","text":"n"},{"label":"B","text":"l"},{"label":"C","text":"m"},{"label":"D","text":"s"}],"answer":1,"solution":"Azimuthal quantum number (l) determines orbital shape (s-&gt;0, p-&gt;1, d-&gt;2)."},{"id":1541,"text":"The chemical formula of rust is:","options":[{"label":"A","text":"FeO"},{"label":"B","text":"FeO"},{"label":"C","text":"FeO.xHO"},{"label":"D","text":"FeO"}],"answer":2,"solution":"Rust is hydrated iron(III) oxide, FeO.xHO."},{"id":1542,"text":"What is the type of bond that occurs between two atoms with a large difference in electronegativity?","options":[{"label":"A","text":"Covalent bond"},{"label":"B","text":"Ionic bond"},{"label":"C","text":"Hydrogen bond"},{"label":"D","text":"Van der Waals bond"}],"answer":1,"solution":"Ionic bonds occur between two atoms with a large difference in electronegativity, resulting in the transfer of electrons and the formation of ions."},{"id":1547,"text":"Which of these is an example of an aromatic compound?","options":[{"label":"A","text":"Cyclohexane"},{"label":"B","text":"Benzene"},{"label":"C","text":"Cyclohexene"},{"label":"D","text":"1,3-cyclohexadiene"}],"answer":1,"solution":"Benzene (CH) is aromatic with delocalized 6pi electrons."},{"id":1548,"text":"The oxide that turns red litmus blue is:","options":[{"label":"A","text":"CO"},{"label":"B","text":"SO"},{"label":"C","text":"NaO"},{"label":"D","text":"PO"}],"answer":2,"solution":"NaO is basic oxide -&gt; turns red litmus blue. CO, SO, PO are acidic."},{"id":1552,"text":"Which of the following is an isotope of hydrogen?","options":[{"label":"A","text":"Protium"},{"label":"B","text":"Deuterium"},{"label":"C","text":"Tritium"},{"label":"D","text":"All of these"}],"answer":3,"solution":"Protium (H), Deuterium (^2H), and Tritium (H) are all isotopes of hydrogen."},{"id":1555,"text":"The catalyst used in the contact process for HSO is:","options":[{"label":"A","text":"VO"},{"label":"B","text":"Fe"},{"label":"C","text":"Ni"},{"label":"D","text":"Pt"}],"answer":0,"solution":"Contact process uses VO (vanadium pentoxide) as catalyst."},{"id":1560,"text":"What is the type of bond that occurs between two atoms with a large difference in electronegativity?","options":[{"label":"A","text":"Covalent bond"},{"label":"B","text":"Ionic bond"},{"label":"C","text":"Hydrogen bond"},{"label":"D","text":"Van der Waals bond"}],"answer":1,"solution":"Ionic bonds occur between two atoms with a large difference in electronegativity, resulting in the transfer of electrons and the formation of ions."},{"id":1563,"text":"For the reaction N2(g) + 3H2(g) = 2NH3(g), the partial pressures at a given instant are P(N2) = 0.2 atm, P(H2) = 0.1 atm and P(NH3) = 0.02 atm. What is the reaction quotient Qp at that instant?","options":[{"label":"A","text":"0.25 atm^-2"},{"label":"B","text":"2.0 atm^-2"},{"label":"C","text":"10.0 atm^-2"},{"label":"D","text":"0.05 atm^-2"}],"answer":1,"solution":"Qp = P(NH3)^2 / [P(N2) x P(H2)^3] = (0.02)^2 / (0.2 x 0.1^3) = 0.0004 / 0.0002 = 2.0 atm^-2. Option B is correct."},{"id":1574,"text":"pH scale ranges from:","options":[{"label":"A","text":"0 to 7"},{"label":"B","text":"7 to 14"},{"label":"C","text":"0 to 14"},{"label":"D","text":"1 to 10"}],"answer":2,"solution":"pH scale ranges 0-14 (0-6 acidic, 7 neutral, 8-14 basic)."},{"id":1577,"text":"What is the type of reaction that involves the loss of electrons by a species?","options":[{"label":"A","text":"Oxidation reaction"},{"label":"B","text":"Reduction reaction"},{"label":"C","text":"Acid-base reaction"},{"label":"D","text":"Neutralization reaction"}],"answer":0,"solution":"An oxidation reaction is a type of reaction that involves the loss of electrons by a species."},{"id":1584,"text":"The IUPAC name of CHCOOH is:","options":[{"label":"A","text":"Formic acid"},{"label":"B","text":"Ethanoic acid"},{"label":"C","text":"Acetic acid"},{"label":"D","text":"Methanoic acid"}],"answer":1,"solution":"CHCOOH -&gt; 2 carbons -&gt; Ethanoic acid (common: acetic acid)."},{"id":1586,"text":"What is the type of isomerism that occurs when molecules have the same molecular formula and sequence of bonded atoms, but differ in the three-dimensional arrangement of their atoms?","options":[{"label":"A","text":"Structural isomerism"},{"label":"B","text":"Stereoisomerism"},{"label":"C","text":"Enantiomerism"},{"label":"D","text":"Tautomerism"}],"answer":1,"solution":"Stereoisomerism occurs when molecules have the same molecular formula and sequence of bonded atoms, but differ in the three-dimensional arrangement of their atoms."},{"id":1593,"text":"Which gas is produced when zinc reacts with dilute HSO?","options":[{"label":"A","text":"Oxygen"},{"label":"B","text":"Chlorine"},{"label":"C","text":"Hydrogen"},{"label":"D","text":"Carbon dioxide"}],"answer":2,"solution":"Zn + HSO -&gt; ZnSO + H-&gt;. Hydrogen gas is produced."},{"id":1596,"text":"Which of the following has covalent bonding?","options":[{"label":"A","text":"NaCl"},{"label":"B","text":"HO"},{"label":"C","text":"KBr"},{"label":"D","text":"CaO"}],"answer":1,"solution":"HO has covalent bonds (sharing of electrons). NaCl, KBr, CaO are ionic."},{"id":1597,"text":"The most stable allotrope of carbon is:","options":[{"label":"A","text":"Diamond"},{"label":"B","text":"Graphite"},{"label":"C","text":"Fullerene"},{"label":"D","text":"Coal"}],"answer":1,"solution":"Graphite is the most stable allotrope of carbon at room temperature."},{"id":1598,"text":"The bond angle in water is approximately:","options":[{"label":"A","text":"90 degrees"},{"label":"B","text":"109.5 degrees"},{"label":"C","text":"104.5 degrees"},{"label":"D","text":"120 degrees"}],"answer":2,"solution":"Water has bent shape with 104.5 degrees  angle due to lone pair repulsion."},{"id":1601,"text":"The number of oxygen atoms in 1 mole of HSO is:","options":[{"label":"A","text":"4 x 6.022 x 10^2"},{"label":"B","text":"6.022 x 10^2"},{"label":"C","text":"2 x 6.022 x 10^2"},{"label":"D","text":"7 x 6.022 x 10^2"}],"answer":0,"solution":"1 molecule of HSO has 4 O atoms. 1 mole has 4 x NA = 4 x 6.022 x 10^2 atoms."},{"id":1604,"text":"Which of the following reagents would distinguish between ethanal and propanone?","options":[{"label":"A","text":"Tollen&#39;s reagent"},{"label":"B","text":"Fehling&#39;s solution"},{"label":"C","text":"Benedict&#39;s solution"},{"label":"D","text":"All of the above"}],"answer":3,"solution":"Ethanal (CH3CHO) is an aldehyde, while propanone (CH3COCH3) is a ketone. Aldehydes can be easily oxidized to carboxylic acids by mild oxidizing agents, whereas ketones are generally resistant to oxidation by mild agents. Tollen&#39;s reagent (ammoniacal silver nitrate), Fehling&#39;s solution (alkaline solution of CuSO4 and sodium potassium tartrate), and Benedict&#39;s solution (alkaline solution of CuSO4 and sodium citrate) are all mild oxidizing agents used to detect aldehydes.\r\nEthanal, being an aldehyde, will give a positive test with Tollen&#39;s reagent (forming a silver mirror), Fehling&#39;s solution (forming a red precipitate of Cu2O), and Benedict&#39;s solution (forming a red precipitate of Cu2O).\r\nPropanone, being a ketone, will not react with any of these mild oxidizing agents.\r\nTherefore, all the listed reagents can distinguish between ethanal and propanone."},{"id":1606,"text":"The number of electrons in Na ion is:","options":[{"label":"A","text":"11"},{"label":"B","text":"10"},{"label":"C","text":"12"},{"label":"D","text":"9"}],"answer":1,"solution":"Na (11 e) -&gt; Na loses 1 e -&gt; 10 electrons."},{"id":1608,"text":"Which of the following is a noble gas?","options":[{"label":"A","text":"Hydrogen"},{"label":"B","text":"Nitrogen"},{"label":"C","text":"Argon"},{"label":"D","text":"Chlorine"}],"answer":2,"solution":"Argon (Ar) is a noble gas in Group 18 with a full valence shell."},{"id":1610,"text":"Which of the following is NOT a polymer?","options":[{"label":"A","text":"Nylon"},{"label":"B","text":"Cellulose"},{"label":"C","text":"Glucose"},{"label":"D","text":"PVC"}],"answer":2,"solution":"Glucose is a monomer (monosaccharide), not a polymer. Nylon, cellulose, PVC are polymers."},{"id":1611,"text":"The number of atoms in 1 mole of any substance is:","options":[{"label":"A","text":"6.022 x 10^2"},{"label":"B","text":"Avogadro&#39;s number"},{"label":"C","text":"6.022 x 10^2"},{"label":"D","text":"Both A and B"}],"answer":1,"solution":"1 mole = 6.022 x 10^2 particles = Avogadro&#39;s number."},{"id":1613,"text":"Which of the following reactions will NOT yield an alkyl halide?","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""}],"answer":3,"solution":"Reaction A (Lucas test) yields CHCHCl. Reaction B (free radical halogenation) yields CHCH(Cl)CH and CHCHCHCl. Reaction C (hydrohalogenation of propene, Markovnikov&#39;s rule) yields CHCH(Br)CH. Reaction D (reaction of carboxylic acid with PCl) yields an acyl chloride (CHCHCOCl), not an alkyl halide."},{"id":1617,"text":"Which of the following statements is INCORRECT regarding the characteristics of physisorption?","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""}],"answer":2,"solution":"Physisorption is non-specific in nature because it occurs due to weak van der Waals forces which are universal. Chemisorption, on the other hand, is highly specific and involves the formation of chemical bonds between adsorbate and adsorbent."},{"id":1618,"text":"Which of the following reactions represents a Williamson ether synthesis?","options":[{"label":"A","text":"R-OH + Na -&gt; R-ONa + 1/2 H"},{"label":"B","text":"R-ONa + R&#39;-X -&gt; R-O-R&#39; + NaX"},{"label":"C","text":"R-OH + HX -&gt; R-X + HO"},{"label":"D","text":"R-CHO + R&#39;-MgBr -&gt; R-CH(OMgBr)-R&#39;"}],"answer":1,"solution":"Williamson ether synthesis involves the reaction of an alkoxide (formed from an alcohol and a strong base like Na) with an alkyl halide to form an ether. Option B correctly depicts this reaction."},{"id":1623,"text":"The process of electrolysis is based on:","options":[{"label":"A","text":"Chemical effect of current"},{"label":"B","text":"Magnetic effect of current"},{"label":"C","text":"Redox reactions"},{"label":"D","text":"Heating effect"}],"answer":2,"solution":"Electrolysis involves redox reactions at electrodes driven by electric current."},{"id":1626,"text":"Which of the following reagents can be used to distinguish between propanal and propanone?","options":[{"label":"A","text":"Tollen&#39;s reagent"},{"label":"B","text":"Fehling&#39;s solution"},{"label":"C","text":"Benedict&#39;s solution"},{"label":"D","text":"All of the above"}],"answer":3,"solution":"Propanal is an aldehyde (CHCHCHO), and propanone is a ketone (CHCOCH).\r\nAldehydes are generally more easily oxidized than ketones. They can reduce mild oxidizing agents, while ketones typically cannot (except under harsh conditions or specific structural features like alpha-hydroxy ketones).\r\n\r\n1.  **Tollen&#39;s reagent (ammoniacal silver nitrate):** Aldehydes reduce Tollen&#39;s reagent to metallic silver, forming a &#39;silver mirror&#39; on the test tube. Ketones do not react.\r\n2.  **Fehling&#39;s solution (alkaline solution of copper(II) sulfate complexed with tartrate):** Aldehydes reduce the blue Cu^2 ions to red precipitate of cuprous oxide (CuO). Ketones do not react.\r\n3.  **Benedict&#39;s solution (alkaline solution of copper(II) sulfate complexed with citrate):** Similar to Fehling&#39;s solution, aldehydes reduce the blue Cu^2 ions to red precipitate of cuprous oxide. Ketones do not react.\r\n\r\nSince propanal (an aldehyde) will give a positive test with all three reagents, while propanone (a ketone) will not, all of them can be used to distinguish between the two compounds."},{"id":1630,"text":"The oxide that turns red litmus blue is:","options":[{"label":"A","text":"CO"},{"label":"B","text":"SO"},{"label":"C","text":"NaO"},{"label":"D","text":"PO"}],"answer":2,"solution":"NaO is basic oxide -&gt; turns red litmus blue. CO, SO, PO are acidic."},{"id":1631,"text":"The shape of NH molecule is:","options":[{"label":"A","text":"Trigonal planar"},{"label":"B","text":"Trigonal pyramidal"},{"label":"C","text":"Tetrahedral"},{"label":"D","text":"Linear"}],"answer":1,"solution":"NH: 3 bond pairs + 1 lone pair -&gt; trigonal pyramidal shape."},{"id":1632,"text":"What is the hybridization of the carbon atom in methane?","options":[{"label":"A","text":"sp"},{"label":"B","text":"sp2"},{"label":"C","text":"sp3"},{"label":"D","text":"sp3d"}],"answer":2,"solution":"The carbon atom in methane is bonded to four hydrogen atoms, and its electronic configuration is 1s2 2s2 2p2. To form four equivalent bonds, the carbon atom undergoes sp3 hybridization."},{"id":1639,"text":"The bond angle in water is approximately:","options":[{"label":"A","text":"90 degrees"},{"label":"B","text":"109.5 degrees"},{"label":"C","text":"104.5 degrees"},{"label":"D","text":"120 degrees"}],"answer":2,"solution":"Water has bent shape with 104.5 degrees  angle due to lone pair repulsion."},{"id":1645,"text":"What is the type of reaction that involves the combination of two or more substances to form a new compound?","options":[{"label":"A","text":"Synthesis reaction"},{"label":"B","text":"Decomposition reaction"},{"label":"C","text":"Replacement reaction"},{"label":"D","text":"Combustion reaction"}],"answer":0,"solution":"A synthesis reaction is a type of chemical reaction that involves the combination of two or more substances to form a new compound. This type of reaction is also known as a direct combination reaction."},{"id":1646,"text":"Which of the following shows paramagnetism?","options":[{"label":"A","text":"H"},{"label":"B","text":"N"},{"label":"C","text":"O"},{"label":"D","text":"F"}],"answer":2,"solution":"O has two unpaired electrons in its MO configuration -&gt; paramagnetic."},{"id":1647,"text":"What is the type of reaction that involves the breakdown of a compound into simpler substances using a catalyst?","options":[{"label":"A","text":"Synthesis reaction"},{"label":"B","text":"Decomposition reaction"},{"label":"C","text":"Replacement reaction"},{"label":"D","text":"Catalytic reaction"}],"answer":3,"solution":"A catalytic reaction is a type of chemical reaction that involves the breakdown of a compound into simpler substances using a catalyst. The catalyst speeds up the reaction without being consumed or altered in the process."},{"id":1648,"text":"What is the type of bond that holds atoms together in a molecule?","options":[{"label":"A","text":"Ionic bond"},{"label":"B","text":"Covalent bond"},{"label":"C","text":"Hydrogen bond"},{"label":"D","text":"Van der Waals bond"}],"answer":1,"solution":"A covalent bond is a type of chemical bond that holds atoms together in a molecule. It is formed when two or more atoms share one or more pairs of electrons in order to achieve a more stable electronic configuration."},{"id":1651,"text":"What is the type of bond that occurs between two atoms with a large difference in electronegativity?","options":[{"label":"A","text":"Covalent bond"},{"label":"B","text":"Ionic bond"},{"label":"C","text":"Hydrogen bond"},{"label":"D","text":"Van der Waals bond"}],"answer":1,"solution":"Ionic bonds occur between two atoms with a large difference in electronegativity, resulting in the transfer of electrons and the formation of ions."}]},{"name":"Biology","count":80,"questions":[{"id":1402,"text":"Which organelle is involved in protein synthesis?","options":[{"label":"A","text":"Mitochondria"},{"label":"B","text":"Ribosome"},{"label":"C","text":"Lysosome"},{"label":"D","text":"Golgi body"}],"answer":1,"solution":"Ribosomes (composed of rRNA + proteins) synthesize proteins."},{"id":1403,"text":"Which disease is caused by a virus?","options":[{"label":"A","text":"Cholera"},{"label":"B","text":"Typhoid"},{"label":"C","text":"AIDS"},{"label":"D","text":"Malaria"}],"answer":2,"solution":"AIDS is caused by HIV (virus). Cholera/typhoid: bacteria, Malaria: protozoa."},{"id":1404,"text":"The process of cell division for growth is:","options":[{"label":"A","text":"Meiosis"},{"label":"B","text":"Mitosis"},{"label":"C","text":"Binary fission"},{"label":"D","text":"Budding"}],"answer":1,"solution":"Mitosis produces identical daughter cells for growth and repair."},{"id":1405,"text":"The enzyme that breaks down proteins in stomach is:","options":[{"label":"A","text":"Amylase"},{"label":"B","text":"Pepsin"},{"label":"C","text":"Lipase"},{"label":"D","text":"Trypsin"}],"answer":1,"solution":"Pepsin (in gastric juice) breaks proteins into peptides in acidic medium."},{"id":1406,"text":"Which part of the flower becomes fruit?","options":[{"label":"A","text":"Petal"},{"label":"B","text":"Sepal"},{"label":"C","text":"Ovary"},{"label":"D","text":"Stamen"}],"answer":2,"solution":"After fertilization, the ovary develops into the fruit."},{"id":1407,"text":"The main function of RBC is:","options":[{"label":"A","text":"Blood clotting"},{"label":"B","text":"Oxygen transport"},{"label":"C","text":"Immunity"},{"label":"D","text":"Antibody production"}],"answer":1,"solution":"RBCs (erythrocytes) contain hemoglobin to transport O2 and CO2."},{"id":1408,"text":"Which hormone is called the \"fight or flight\" hormone?","options":[{"label":"A","text":"Insulin"},{"label":"B","text":"Adrenaline"},{"label":"C","text":"Thyroxine"},{"label":"D","text":"Estrogen"}],"answer":1,"solution":"Adrenaline (epinephrine) prepares body for stress (increases HR, BP, etc.)."},{"id":1409,"text":"The smallest bone in the human body is:","options":[{"label":"A","text":"Femur"},{"label":"B","text":"Stapes"},{"label":"C","text":"Patella"},{"label":"D","text":"Phalanges"}],"answer":1,"solution":"Stapes (stirrup bone in middle ear) is the smallest bone (~3 mm)."},{"id":1410,"text":"Which of these is a vestigial organ in humans?","options":[{"label":"A","text":"Liver"},{"label":"B","text":"Heart"},{"label":"C","text":"Appendix"},{"label":"D","text":"Kidney"}],"answer":2,"solution":"Appendix is a vestigial organ (remnant of larger cecum in herbivore ancestors)."},{"id":1411,"text":"The green pigment in plants that traps sunlight is:","options":[{"label":"A","text":"Xanthophyll"},{"label":"B","text":"Chlorophyll"},{"label":"C","text":"Carotene"},{"label":"D","text":"Phycobilin"}],"answer":1,"solution":"Chlorophyll absorbs sunlight (mainly blue and red) for photosynthesis."},{"id":1432,"text":"Which vitamin is water soluble?","options":[{"label":"A","text":"Vitamin A"},{"label":"B","text":"Vitamin D"},{"label":"C","text":"Vitamin C"},{"label":"D","text":"Vitamin K"}],"answer":2,"solution":"Vitamin C and B-complex are water-soluble. A, D, E, K are fat-soluble."},{"id":1433,"text":"The largest gland in the human body is:","options":[{"label":"A","text":"Pancreas"},{"label":"B","text":"Liver"},{"label":"C","text":"Salivary gland"},{"label":"D","text":"Thyroid"}],"answer":1,"solution":"Liver is the largest gland (~1.5 kg) and performs 500+ functions."},{"id":1434,"text":"Which of these is a prokaryote?","options":[{"label":"A","text":"Amoeba"},{"label":"B","text":"Bacteria"},{"label":"C","text":"Yeast"},{"label":"D","text":"Paramecium"}],"answer":1,"solution":"Bacteria are prokaryotes (no membrane-bound nucleus/organelles)."},{"id":1435,"text":"The universal donor blood group is:","options":[{"label":"A","text":"A"},{"label":"B","text":"B"},{"label":"C","text":"AB"},{"label":"D","text":"O"}],"answer":3,"solution":"O negative is universal donor (no A/B antigens, no Rh factor)."},{"id":1436,"text":"The respiratory pigment in human blood is:","options":[{"label":"A","text":"Chlorophyll"},{"label":"B","text":"Hemoglobin"},{"label":"C","text":"Melanin"},{"label":"D","text":"Myoglobin"}],"answer":1,"solution":"Hemoglobin in RBCs transports O2 from lungs to tissues."},{"id":1437,"text":"Which part of the brain controls balance and coordination?","options":[{"label":"A","text":"Cerebrum"},{"label":"B","text":"Cerebellum"},{"label":"C","text":"Medulla"},{"label":"D","text":"Hypothalamus"}],"answer":1,"solution":"Cerebellum coordinates voluntary movements, balance, and posture."},{"id":1438,"text":"The number of chromosomes in human cells is:","options":[{"label":"A","text":"23"},{"label":"B","text":"46"},{"label":"C","text":"48"},{"label":"D","text":"44"}],"answer":1,"solution":"Humans have 23 pairs = 46 chromosomes (22 autosomes + 1 sex chromosome pair)."},{"id":1439,"text":"The disease caused by deficiency of insulin is:","options":[{"label":"A","text":"Goiter"},{"label":"B","text":"Diabetes mellitus"},{"label":"C","text":"Anemia"},{"label":"D","text":"Rickets"}],"answer":1,"solution":"Diabetes mellitus is caused by insufficient insulin production or insulin resistance."},{"id":1440,"text":"The DNA structure was discovered by:","options":[{"label":"A","text":"Mendel"},{"label":"B","text":"Darwin"},{"label":"C","text":"Watson and Crick"},{"label":"D","text":"Pasteur"}],"answer":2,"solution":"Watson and Crick proposed the double helix structure of DNA in 1953."},{"id":1441,"text":"Which chamber of the heart pumps blood to the lungs?","options":[{"label":"A","text":"Left atrium"},{"label":"B","text":"Left ventricle"},{"label":"C","text":"Right atrium"},{"label":"D","text":"Right ventricle"}],"answer":3,"solution":"Right ventricle pumps deoxygenated blood to lungs via pulmonary artery."},{"id":1452,"text":"The powerhouse of the cell is:","options":[{"label":"A","text":"Nucleus"},{"label":"B","text":"Ribosome"},{"label":"C","text":"Mitochondria"},{"label":"D","text":"Golgi apparatus"}],"answer":2,"solution":"Mitochondria produce ATP through cellular respiration, hence called the powerhouse of the cell."},{"id":1453,"text":"Which vitamin is produced in the skin on exposure to sunlight?","options":[{"label":"A","text":"Vitamin A"},{"label":"B","text":"Vitamin D"},{"label":"C","text":"Vitamin C"},{"label":"D","text":"Vitamin B12"}],"answer":1,"solution":"UV rays convert 7-dehydrocholesterol to Vitamin D3 in the skin."},{"id":1454,"text":"The human heart has how many chambers?","options":[{"label":"A","text":"2"},{"label":"B","text":"3"},{"label":"C","text":"4"},{"label":"D","text":"5"}],"answer":2,"solution":"Human heart has 4 chambers: 2 atria and 2 ventricles."},{"id":1455,"text":"DNA replication is which type of process?","options":[{"label":"A","text":"Conservative"},{"label":"B","text":"Semiconservative"},{"label":"C","text":"Dispersive"},{"label":"D","text":"Random"}],"answer":1,"solution":"DNA replication follows the semiconservative model as demonstrated by Meselson and Stahl."},{"id":1456,"text":"Which hormone regulates blood sugar level?","options":[{"label":"A","text":"Thyroxine"},{"label":"B","text":"Insulin"},{"label":"C","text":"Adrenaline"},{"label":"D","text":"Estrogen"}],"answer":1,"solution":"Insulin lowers blood glucose, while glucagon raises it."},{"id":1467,"text":"The longest bone in the human body is:","options":[{"label":"A","text":"Humerus"},{"label":"B","text":"Femur"},{"label":"C","text":"Tibia"},{"label":"D","text":"Fibula"}],"answer":1,"solution":"Femur (thigh bone) is the longest and strongest bone in the human body."},{"id":1468,"text":"Which organ is responsible for blood filtration?","options":[{"label":"A","text":"Liver"},{"label":"B","text":"Kidney"},{"label":"C","text":"Heart"},{"label":"D","text":"Lungs"}],"answer":1,"solution":"Kidneys filter blood through nephrons, removing waste and excess water to form urine."},{"id":1469,"text":"The pigment responsible for skin color is:","options":[{"label":"A","text":"Chlorophyll"},{"label":"B","text":"Haemoglobin"},{"label":"C","text":"Melanin"},{"label":"D","text":"Carotene"}],"answer":2,"solution":"Melanin produced by melanocytes determines skin, hair, and eye color."},{"id":1470,"text":"Blood group with no antigens on RBC is:","options":[{"label":"A","text":"A"},{"label":"B","text":"B"},{"label":"C","text":"AB"},{"label":"D","text":"O"}],"answer":3,"solution":"Blood group O has no A or B antigens on RBCs but has both anti-A and anti-B antibodies."},{"id":1471,"text":"Which enzyme breaks down starch in the mouth?","options":[{"label":"A","text":"Amylase"},{"label":"B","text":"Pepsin"},{"label":"C","text":"Lipase"},{"label":"D","text":"Trypsin"}],"answer":0,"solution":"Salivary amylase (ptyalin) breaks down starch into maltose in the oral cavity."},{"id":1474,"text":"Which of these is a vestigial organ in humans?","options":[{"label":"A","text":"Liver"},{"label":"B","text":"Heart"},{"label":"C","text":"Appendix"},{"label":"D","text":"Kidney"}],"answer":2,"solution":"Appendix is a vestigial organ (remnant of larger cecum in herbivore ancestors)."},{"id":1480,"text":"During DNA replication, which enzyme is responsible for synthesizing the new DNA strand by adding nucleotides complementary to the template strand?","options":[{"label":"A","text":"DNA ligase"},{"label":"B","text":"DNA helicase"},{"label":"C","text":"DNA polymerase"},{"label":"D","text":"Primase"}],"answer":2,"solution":"During DNA replication, several enzymes play crucial roles:*   **DNA ligase:** Joins the Okazaki fragments on the lagging strand by forming phosphodiester bonds.*   **DNA helicase:** Unwinds the DNA double helix by breaking the hydrogen bonds between complementary base pairs, creating the replication fork.*   **DNA polymerase:** This is the primary enzyme responsible for synthesizing new DNA strands. It adds deoxyribonucleotides one by one to the growing DNA strand, using the existing template strand as a guide to ensure complementary base pairing (A with T, G with C).*   **Primase:** Synthesizes short RNA primers, which are necessary for DNA polymerase to initiate DNA synthesis, as DNA polymerase cannot start a new strand from scratch."},{"id":1483,"text":"A person suffers from abnormally high blood glucose levels, frequent urination, and excessive thirst. Which of the following conditions is most likely causing these symptoms?","options":[{"label":"A","text":"Diabetes insipidus"},{"label":"B","text":"Hypothyroidism"},{"label":"C","text":"Diabetes mellitus"},{"label":"D","text":"Addison&#39;s disease"}],"answer":2,"solution":"The symptoms described are classic indicators of Diabetes Mellitus.*   **High blood glucose levels (hyperglycemia):** This is the hallmark of diabetes mellitus, caused by insufficient insulin production or insulin resistance, leading to glucose accumulation in the blood.*   **Frequent urination (polyuria):** High glucose levels in the blood lead to glucose excretion in the urine, drawing water with it due to osmosis, resulting in increased urine output.*   **Excessive thirst (polydipsia):** The loss of fluids through frequent urination leads to dehydration, triggering a sensation of intense thirst.Let&#39;s look at the other options:*   **Diabetes insipidus:** Characterized by frequent urination and thirst, but it is due to a deficiency of ADH (vasopressin) or kidney&#39;s inability to respond to ADH, and does not involve high blood glucose levels.*   **Hypothyroidism:** Caused by low thyroid hormone levels, leading to symptoms like weight gain, fatigue, cold intolerance, and slow metabolism, not primarily high blood glucose.*   **Addison&#39;s disease:** Results from adrenal insufficiency, affecting cortisol and aldosterone production, leading to symptoms like fatigue, weight loss, low blood pressure, and skin hyperpigmentation, not typically high blood glucose."},{"id":1489,"text":"Which of these is a prokaryote?","options":[{"label":"A","text":"Amoeba"},{"label":"B","text":"Bacteria"},{"label":"C","text":"Yeast"},{"label":"D","text":"Paramecium"}],"answer":1,"solution":"Bacteria are prokaryotes (no membrane-bound nucleus/organelles)."},{"id":1492,"text":"DNA replication is which type of process?","options":[{"label":"A","text":"Conservative"},{"label":"B","text":"Semiconservative"},{"label":"C","text":"Dispersive"},{"label":"D","text":"Random"}],"answer":1,"solution":"DNA replication follows the semiconservative model as demonstrated by Meselson and Stahl."},{"id":1494,"text":"The pigment responsible for skin color is:","options":[{"label":"A","text":"Chlorophyll"},{"label":"B","text":"Haemoglobin"},{"label":"C","text":"Melanin"},{"label":"D","text":"Carotene"}],"answer":2,"solution":"Melanin produced by melanocytes determines skin, hair, and eye color."},{"id":1503,"text":"Which enzyme breaks down starch in the mouth?","options":[{"label":"A","text":"Amylase"},{"label":"B","text":"Pepsin"},{"label":"C","text":"Lipase"},{"label":"D","text":"Trypsin"}],"answer":0,"solution":"Salivary amylase (ptyalin) breaks down starch into maltose in the oral cavity."},{"id":1506,"text":"The process of cell division for growth is:","options":[{"label":"A","text":"Meiosis"},{"label":"B","text":"Mitosis"},{"label":"C","text":"Binary fission"},{"label":"D","text":"Budding"}],"answer":1,"solution":"Mitosis produces identical daughter cells for growth and repair."},{"id":1515,"text":"In a DNA double helix, the two strands are joined by hydrogen bonds between the nitrogenous bases. Which of the following statements about these bonds is correct?","options":[{"label":"A","text":"Adenine forms two hydrogen bonds with Guanine."},{"label":"B","text":"Thymine forms three hydrogen bonds with Cytosine."},{"label":"C","text":"Adenine forms two hydrogen bonds with Thymine."},{"label":"D","text":"Guanine forms two hydrogen bonds with Cytosine."}],"answer":2,"solution":"In the DNA double helix, specific base pairing rules are followed, known as Chargaff&#39;s rules:\r\n- Adenine (A) always pairs with Thymine (T) via two hydrogen bonds.\r\n- Guanine (G) always pairs with Cytosine (C) via three hydrogen bonds.\r\n\r\nLet&#39;s evaluate the options:\r\nA) Adenine forms two hydrogen bonds with Guanine. (Incorrect, A pairs with T, G pairs with C)\r\nB) Thymine forms three hydrogen bonds with Cytosine. (Incorrect, T pairs with A via two H-bonds, C pairs with G via three H-bonds)\r\nC) Adenine forms two hydrogen bonds with Thymine. (Correct)\r\nD) Guanine forms two hydrogen bonds with Cytosine. (Incorrect, G pairs with C via three H-bonds)"},{"id":1517,"text":"Which enzyme breaks down starch in the mouth?","options":[{"label":"A","text":"Amylase"},{"label":"B","text":"Pepsin"},{"label":"C","text":"Lipase"},{"label":"D","text":"Trypsin"}],"answer":0,"solution":"Salivary amylase (ptyalin) breaks down starch into maltose in the oral cavity."},{"id":1518,"text":"Which hormone regulates blood sugar level?","options":[{"label":"A","text":"Thyroxine"},{"label":"B","text":"Insulin"},{"label":"C","text":"Adrenaline"},{"label":"D","text":"Estrogen"}],"answer":1,"solution":"Insulin lowers blood glucose, while glucagon raises it."},{"id":1524,"text":"Which organelle is involved in protein synthesis?","options":[{"label":"A","text":"Mitochondria"},{"label":"B","text":"Ribosome"},{"label":"C","text":"Lysosome"},{"label":"D","text":"Golgi body"}],"answer":1,"solution":"Ribosomes (composed of rRNA + proteins) synthesize proteins."},{"id":1529,"text":"The number of chromosomes in human cells is:","options":[{"label":"A","text":"23"},{"label":"B","text":"46"},{"label":"C","text":"48"},{"label":"D","text":"44"}],"answer":1,"solution":"Humans have 23 pairs = 46 chromosomes (22 autosomes + 1 sex chromosome pair)."},{"id":1532,"text":"Which disease is caused by a virus?","options":[{"label":"A","text":"Cholera"},{"label":"B","text":"Typhoid"},{"label":"C","text":"AIDS"},{"label":"D","text":"Malaria"}],"answer":2,"solution":"AIDS is caused by HIV (virus). Cholera/typhoid: bacteria, Malaria: protozoa."},{"id":1533,"text":"The enzyme that breaks down proteins in stomach is:","options":[{"label":"A","text":"Amylase"},{"label":"B","text":"Pepsin"},{"label":"C","text":"Lipase"},{"label":"D","text":"Trypsin"}],"answer":1,"solution":"Pepsin (in gastric juice) breaks proteins into peptides in acidic medium."},{"id":1539,"text":"DNA replication is which type of process?","options":[{"label":"A","text":"Conservative"},{"label":"B","text":"Semiconservative"},{"label":"C","text":"Dispersive"},{"label":"D","text":"Random"}],"answer":1,"solution":"DNA replication follows the semiconservative model as demonstrated by Meselson and Stahl."},{"id":1553,"text":"Which organ is responsible for blood filtration?","options":[{"label":"A","text":"Liver"},{"label":"B","text":"Kidney"},{"label":"C","text":"Heart"},{"label":"D","text":"Lungs"}],"answer":1,"solution":"Kidneys filter blood through nephrons, removing waste and excess water to form urine."},{"id":1554,"text":"The pigment responsible for skin color is:","options":[{"label":"A","text":"Chlorophyll"},{"label":"B","text":"Haemoglobin"},{"label":"C","text":"Melanin"},{"label":"D","text":"Carotene"}],"answer":2,"solution":"Melanin produced by melanocytes determines skin, hair, and eye color."},{"id":1561,"text":"The process of cell division for growth is:","options":[{"label":"A","text":"Meiosis"},{"label":"B","text":"Mitosis"},{"label":"C","text":"Binary fission"},{"label":"D","text":"Budding"}],"answer":1,"solution":"Mitosis produces identical daughter cells for growth and repair."},{"id":1562,"text":"The enzyme that breaks down proteins in stomach is:","options":[{"label":"A","text":"Amylase"},{"label":"B","text":"Pepsin"},{"label":"C","text":"Lipase"},{"label":"D","text":"Trypsin"}],"answer":1,"solution":"Pepsin (in gastric juice) breaks proteins into peptides in acidic medium."},{"id":1564,"text":"What is the primary function of the mitochondria in a cell?","options":[{"label":"A","text":"Protein synthesis"},{"label":"B","text":"Cell division"},{"label":"C","text":"Energy production"},{"label":"D","text":"Waste removal"}],"answer":2,"solution":"The primary function of the mitochondria is to generate energy for the cell through the process of cellular respiration."},{"id":1566,"text":"The green pigment in plants that traps sunlight is:","options":[{"label":"A","text":"Xanthophyll"},{"label":"B","text":"Chlorophyll"},{"label":"C","text":"Carotene"},{"label":"D","text":"Phycobilin"}],"answer":1,"solution":"Chlorophyll absorbs sunlight (mainly blue and red) for photosynthesis."},{"id":1567,"text":"The largest gland in the human body is:","options":[{"label":"A","text":"Pancreas"},{"label":"B","text":"Liver"},{"label":"C","text":"Salivary gland"},{"label":"D","text":"Thyroid"}],"answer":1,"solution":"Liver is the largest gland (~1.5 kg) and performs 500+ functions."},{"id":1568,"text":"Which enzyme breaks down starch in the mouth?","options":[{"label":"A","text":"Amylase"},{"label":"B","text":"Pepsin"},{"label":"C","text":"Lipase"},{"label":"D","text":"Trypsin"}],"answer":0,"solution":"Salivary amylase (ptyalin) breaks down starch into maltose in the oral cavity."},{"id":1571,"text":"Which vitamin is water soluble?","options":[{"label":"A","text":"Vitamin A"},{"label":"B","text":"Vitamin D"},{"label":"C","text":"Vitamin C"},{"label":"D","text":"Vitamin K"}],"answer":2,"solution":"Vitamin C and B-complex are water-soluble. A, D, E, K are fat-soluble."},{"id":1572,"text":"The disease caused by deficiency of insulin is:","options":[{"label":"A","text":"Goiter"},{"label":"B","text":"Diabetes mellitus"},{"label":"C","text":"Anemia"},{"label":"D","text":"Rickets"}],"answer":1,"solution":"Diabetes mellitus is caused by insufficient insulin production or insulin resistance."},{"id":1575,"text":"What is the process by which water moves through a plant, from the roots to the leaves, and is then released into the air as water vapor?","options":[{"label":"A","text":"Respiration"},{"label":"B","text":"Photosynthesis"},{"label":"C","text":"Transpiration"},{"label":"D","text":"Evaporation"}],"answer":2,"solution":"Transpiration is the process by which water moves through a plant, from the roots to the leaves, and is then released into the air as water vapor."},{"id":1578,"text":"Which hormone is called the &quot;fight or flight&quot; hormone?","options":[{"label":"A","text":"Insulin"},{"label":"B","text":"Adrenaline"},{"label":"C","text":"Thyroxine"},{"label":"D","text":"Estrogen"}],"answer":1,"solution":"Adrenaline (epinephrine) prepares body for stress (increases HR, BP, etc.)."},{"id":1581,"text":"Blood group with no antigens on RBC is:","options":[{"label":"A","text":"A"},{"label":"B","text":"B"},{"label":"C","text":"AB"},{"label":"D","text":"O"}],"answer":3,"solution":"Blood group O has no A or B antigens on RBCs but has both anti-A and anti-B antibodies."},{"id":1582,"text":"A person suffers from abnormally high blood glucose levels, frequent urination, and excessive thirst. Which of the following conditions is most likely causing these symptoms?","options":[{"label":"A","text":"Diabetes insipidus"},{"label":"B","text":"Hypothyroidism"},{"label":"C","text":"Diabetes mellitus"},{"label":"D","text":"Addison&#39;s disease"}],"answer":2,"solution":"The symptoms described are classic indicators of Diabetes Mellitus.\r\n\r\n*   **High blood glucose levels (hyperglycemia):** This is the hallmark of diabetes mellitus, caused by insufficient insulin production or insulin resistance, leading to glucose accumulation in the blood.\r\n*   **Frequent urination (polyuria):** High glucose levels in the blood lead to glucose excretion in the urine, drawing water with it due to osmosis, resulting in increased urine output.\r\n*   **Excessive thirst (polydipsia):** The loss of fluids through frequent urination leads to dehydration, triggering a sensation of intense thirst.\r\n\r\nLet&#39;s look at the other options:\r\n*   **Diabetes insipidus:** Characterized by frequent urination and thirst, but it is due to a deficiency of ADH (vasopressin) or kidney&#39;s inability to respond to ADH, and does not involve high blood glucose levels.\r\n*   **Hypothyroidism:** Caused by low thyroid hormone levels, leading to symptoms like weight gain, fatigue, cold intolerance, and slow metabolism, not primarily high blood glucose.\r\n*   **Addison&#39;s disease:** Results from adrenal insufficiency, affecting cortisol and aldosterone production, leading to symptoms like fatigue, weight loss, low blood pressure, and skin hyperpigmentation, not typically high blood glucose."},{"id":1583,"text":"Which organelle is involved in protein synthesis?","options":[{"label":"A","text":"Mitochondria"},{"label":"B","text":"Ribosome"},{"label":"C","text":"Lysosome"},{"label":"D","text":"Golgi body"}],"answer":1,"solution":"Ribosomes (composed of rRNA + proteins) synthesize proteins."},{"id":1588,"text":"The respiratory pigment in human blood is:","options":[{"label":"A","text":"Chlorophyll"},{"label":"B","text":"Hemoglobin"},{"label":"C","text":"Melanin"},{"label":"D","text":"Myoglobin"}],"answer":1,"solution":"Hemoglobin in RBCs transports O from lungs to tissues."},{"id":1589,"text":"Which part of the brain controls balance and coordination?","options":[{"label":"A","text":"Cerebrum"},{"label":"B","text":"Cerebellum"},{"label":"C","text":"Medulla"},{"label":"D","text":"Hypothalamus"}],"answer":1,"solution":"Cerebellum coordinates voluntary movements, balance, and posture."},{"id":1590,"text":"Which of the following hormones is secreted by the anterior pituitary gland?","options":[{"label":"A","text":"Antidiuretic hormone (ADH)"},{"label":"B","text":"Oxytocin"},{"label":"C","text":"Growth hormone (GH)"},{"label":"D","text":"Melatonin"}],"answer":2,"solution":"The anterior pituitary gland secretes several hormones, including Growth Hormone (GH), Thyroid-Stimulating Hormone (TSH), Adrenocorticotropic Hormone (ACTH), Follicle-Stimulating Hormone (FSH), Luteinizing Hormone (LH), and Prolactin. ADH and Oxytocin are secreted by the posterior pituitary, and Melatonin is secreted by the pineal gland."},{"id":1591,"text":"Which part of the nephron is impermeable to water but permeable to salts, leading to the dilution of filtrate?","options":[{"label":"A","text":"Proximal Convoluted Tubule (PCT)"},{"label":"B","text":"Descending limb of Henle&#39;s loop"},{"label":"C","text":"Ascending limb of Henle&#39;s loop"},{"label":"D","text":"Distal Convoluted Tubule (DCT)"}],"answer":2,"solution":"The ascending limb of Henle&#39;s loop is characterized by its impermeability to water. However, it actively reabsorbs sodium and chloride ions (and some other electrolytes) from the filtrate into the interstitial fluid. As solutes are removed from the filtrate but water is retained, the filtrate becomes progressively more dilute as it moves up the ascending limb. \r\n- PCT: Permeable to both water and salts, involved in bulk reabsorption.\r\n- Descending limb of Henle&#39;s loop: Highly permeable to water but largely impermeable to electrolytes, leading to concentration of filtrate.\r\n- DCT: Involved in conditional reabsorption of water and sodium, not primarily responsible for initial dilution due to impermeability to water while being permeable to salts."},{"id":1592,"text":"Which vitamin is produced in the skin on exposure to sunlight?","options":[{"label":"A","text":"Vitamin A"},{"label":"B","text":"Vitamin D"},{"label":"C","text":"Vitamin C"},{"label":"D","text":"Vitamin B12"}],"answer":1,"solution":"UV rays convert 7-dehydrocholesterol to Vitamin D in the skin."},{"id":1602,"text":"During DNA replication, which enzyme is responsible for synthesizing the new DNA strand by adding nucleotides complementary to the template strand?","options":[{"label":"A","text":"DNA ligase"},{"label":"B","text":"DNA helicase"},{"label":"C","text":"DNA polymerase"},{"label":"D","text":"Primase"}],"answer":2,"solution":"During DNA replication, several enzymes play crucial roles:\r\n\r\n*   **DNA ligase:** Joins the Okazaki fragments on the lagging strand by forming phosphodiester bonds.\r\n*   **DNA helicase:** Unwinds the DNA double helix by breaking the hydrogen bonds between complementary base pairs, creating the replication fork.\r\n*   **DNA polymerase:** This is the primary enzyme responsible for synthesizing new DNA strands. It adds deoxyribonucleotides one by one to the growing DNA strand, using the existing template strand as a guide to ensure complementary base pairing (A with T, G with C).\r\n*   **Primase:** Synthesizes short RNA primers, which are necessary for DNA polymerase to initiate DNA synthesis, as DNA polymerase cannot start a new strand from scratch."},{"id":1612,"text":"Which of the following is a primary lymphoid organ where B-lymphocytes mature?","options":[{"label":"A","text":""},{"label":"B","text":""},{"label":"C","text":""},{"label":"D","text":""}],"answer":2,"solution":"Primary lymphoid organs are sites where lymphocytes mature and proliferate. The bone marrow is the primary lymphoid organ where all blood cells, including lymphocytes, are produced, and B-lymphocytes mature. T-lymphocytes mature in the thymus."},{"id":1616,"text":"What is the term for the process by which plants convert light energy into chemical energy?","options":[{"label":"A","text":"Respiration"},{"label":"B","text":"Photosynthesis"},{"label":"C","text":"Fermentation"},{"label":"D","text":"Transpiration"}],"answer":1,"solution":"Photosynthesis is the process by which plants, algae, and some bacteria convert light energy from the sun into chemical energy in the form of glucose. This process occurs in specialized organelles called chloroplasts and is essential for life on Earth."},{"id":1619,"text":"The number of chromosomes in human cells is:","options":[{"label":"A","text":"23"},{"label":"B","text":"46"},{"label":"C","text":"48"},{"label":"D","text":"44"}],"answer":1,"solution":"Humans have 23 pairs = 46 chromosomes (22 autosomes + 1 sex chromosome pair)."},{"id":1622,"text":"Which hormone is called the &quot;fight or flight&quot; hormone?","options":[{"label":"A","text":"Insulin"},{"label":"B","text":"Adrenaline"},{"label":"C","text":"Thyroxine"},{"label":"D","text":"Estrogen"}],"answer":1,"solution":"Adrenaline (epinephrine) prepares body for stress (increases HR, BP, etc.)."},{"id":1625,"text":"The number of chromosomes in human cells is:","options":[{"label":"A","text":"23"},{"label":"B","text":"46"},{"label":"C","text":"48"},{"label":"D","text":"44"}],"answer":1,"solution":"Humans have 23 pairs = 46 chromosomes (22 autosomes + 1 sex chromosome pair)."},{"id":1629,"text":"The universal donor blood group is:","options":[{"label":"A","text":"A"},{"label":"B","text":"B"},{"label":"C","text":"AB"},{"label":"D","text":"O"}],"answer":3,"solution":"O negative is universal donor (no A/B antigens, no Rh factor)."},{"id":1633,"text":"The process of DNA replication is described as semi-conservative. What does this imply?","options":[{"label":"A","text":"Each new DNA molecule consists of two entirely new strands."},{"label":"B","text":"Each new DNA molecule consists of one original strand and one newly synthesized strand."},{"label":"C","text":"The DNA molecule breaks down completely and reforms into new strands."},{"label":"D","text":"The replication process is only about 50% efficient."}],"answer":1,"solution":"Semi-conservative replication means that each daughter DNA molecule contains one strand from the parent molecule and one newly synthesized strand."},{"id":1635,"text":"The respiratory pigment in human blood is:","options":[{"label":"A","text":"Chlorophyll"},{"label":"B","text":"Hemoglobin"},{"label":"C","text":"Melanin"},{"label":"D","text":"Myoglobin"}],"answer":1,"solution":"Hemoglobin in RBCs transports O from lungs to tissues."},{"id":1636,"text":"Which hormone regulates blood sugar level?","options":[{"label":"A","text":"Thyroxine"},{"label":"B","text":"Insulin"},{"label":"C","text":"Adrenaline"},{"label":"D","text":"Estrogen"}],"answer":1,"solution":"Insulin lowers blood glucose, while glucagon raises it."},{"id":1638,"text":"What is the process by which water moves through a plant, from the roots to the leaves, and is then released into the air as water vapor?","options":[{"label":"A","text":"Respiration"},{"label":"B","text":"Photosynthesis"},{"label":"C","text":"Transpiration"},{"label":"D","text":"Evaporation"}],"answer":2,"solution":"Transpiration is the process by which water moves through a plant, from the roots to the leaves, and is then released into the air as water vapor."},{"id":1640,"text":"What is the term for the process by which plants convert light energy into chemical energy?","options":[{"label":"A","text":"Respiration"},{"label":"B","text":"Photosynthesis"},{"label":"C","text":"Decomposition"},{"label":"D","text":"Fermentation"}],"answer":1,"solution":"Photosynthesis is the process by which plants convert light energy into chemical energy."},{"id":1642,"text":"What is the term for the process by which water moves through a plant, from the roots to the leaves?","options":[{"label":"A","text":"Respiration"},{"label":"B","text":"Photosynthesis"},{"label":"C","text":"Transpiration"},{"label":"D","text":"Evaporation"}],"answer":2,"solution":"Transpiration is the process by which water moves through a plant, from the roots to the leaves, and is then released into the air as water vapor. This process is an important part of the water cycle and helps to regulate the plant&#39;s temperature and maintain its water balance."},{"id":1644,"text":"What is the term for the process by which an organism&#39;s genetic information is used to synthesize proteins and other molecules in response to environmental stimuli?","options":[{"label":"A","text":"Hereditary"},{"label":"B","text":"Genetic drift"},{"label":"C","text":"Gene expression"},{"label":"D","text":"Cell division"}],"answer":2,"solution":"Gene expression is the process by which an organism&#39;s genetic information is used to synthesize proteins and other molecules in response to environmental stimuli. This involves the transcription of DNA into RNA and the translation of RNA into protein, and is essential for the proper functioning of the organism."}]},{"name":"Zoology","count":20,"questions":[{"id":1652,"text":"Which of the following structures in a neuron is primarily responsible for receiving signals from other neurons or sensory receptors?","options":[{"label":"A","text":"Axon"},{"label":"B","text":"Dendrite"},{"label":"C","text":"Myelin sheath"},{"label":"D","text":"Node of Ranvier"}],"answer":1,"solution":"Dendrites are branched extensions of the neuron specifically designed to receive incoming electrical and chemical signals. The axon conducts impulses away from the cell body, the myelin sheath insulates the axon for faster transmission, and the node of Ranvier is a gap in the myelin where saltatory conduction occurs."},{"id":1653,"text":"In humans, the primary function of the thymus gland during childhood is:","options":[{"label":"A","text":"Production of insulin"},{"label":"B","text":"Maturation of T-lymphocytes"},{"label":"C","text":"Secretion of adrenaline"},{"label":"D","text":"Regulation of blood calcium levels"}],"answer":1,"solution":"The thymus gland is crucial for the development and maturation of T-lymphocytes (T-cells), which are essential for adaptive immunity. Insulin is produced by the pancreas, adrenaline by the adrenal medulla, and blood calcium regulation involves the parathyroid glands."},{"id":1654,"text":"Which of the following pairs represents a correct match between an animal phylum and a characteristic feature?","options":[{"label":"A","text":"Porifera - Presence of true tissues"},{"label":"B","text":"Cnidaria - Radial symmetry and cnidocytes"},{"label":"C","text":"Annelida - Segmented body with jointed appendages"},{"label":"D","text":"Arthropoda - Soft unsegmented body"}],"answer":1,"solution":"Cnidarians exhibit radial symmetry and possess specialized stinging cells called cnidocytes. Poriferans lack true tissues; Annelids have segments but lack jointed appendages (that is a trait of Arthropods); Arthropods have hard exoskeletons and jointed legs, not soft unsegmented bodies."},{"id":1655,"text":"The evolutionary trend towards the development of wings in birds and bats is an example of:","options":[{"label":"A","text":"Homology"},{"label":"B","text":"Analogy (Convergent Evolution)"},{"label":"C","text":"Vestigiality"},{"label":"D","text":"Genetic Drift"}],"answer":1,"solution":"Wings in birds and bats are analogous structures because they evolved independently for flight in different lineages, making this convergent evolution. Homology refers to similar structures due to common ancestry; vestigiality refers to reduced organs with no function."},{"id":1656,"text":"Which of the following blood groups is considered the universal donor for red blood cell transfusions?","options":[{"label":"A","text":"A+"},{"label":"B","text":"B-"},{"label":"C","text":"AB+"},{"label":"D","text":"O-"}],"answer":3,"solution":"Blood group O-negative lacks A, B, and Rh antigens on the red blood cells, making it safe to transfuse into recipients of any blood type. A+ has A antigen and Rh factor; B- has B antigen; AB+ has both A and B antigens, limiting their compatibility."},{"id":1657,"text":"The process by which water evaporates from the leaves of a plant, creating a suction force that pulls water up from the roots, is called:","options":[{"label":"A","text":"Translocation"},{"label":"B","text":"Photosynthesis"},{"label":"C","text":"Transpiration"},{"label":"D","text":"Osmosis"}],"answer":2,"solution":"Transpiration is the evaporation of water from plant surfaces (mainly stomata) which generates negative pressure to pull water upward. Translocation refers to sugar transport; photosynthesis converts light to chemical energy; osmosis is passive water movement across a membrane."},{"id":1658,"text":"Which of the following hormones acts as a counter-regulatory hormone to insulin by raising blood glucose levels?","options":[{"label":"A","text":"Insulin"},{"label":"B","text":"Glucagon"},{"label":"C","text":"Thyroxine"},{"label":"D","text":"Melatonin"}],"answer":1,"solution":"Glucagon is secreted by the pancreas when blood sugar is low and stimulates glycogen breakdown to raise glucose levels. Insulin lowers blood sugar; Thyroxine regulates metabolism but does not directly oppose insulin's immediate effect on glucose; Melatonin regulates sleep cycles."},{"id":1659,"text":"In the human circulatory system, which component of the blood is primarily responsible for clotting?","options":[{"label":"A","text":"Red Blood Cells"},{"label":"B","text":"White Blood Cells"},{"label":"C","text":"Platelets"},{"label":"D","text":"Plasma"}],"answer":2,"solution":"Platelets (thrombocytes) are cell fragments that aggregate at injury sites to form a plug and release factors initiating the clotting cascade. Red blood cells transport oxygen; white blood cells fight infection; plasma is the liquid medium carrying dissolved substances."},{"id":1660,"text":"Which of the following organisms exhibits metamorphosis during its life cycle?","options":[{"label":"A","text":"Frog"},{"label":"B","text":"Earthworm"},{"label":"C","text":"Penguin"},{"label":"D","text":"Jellyfish"}],"answer":0,"solution":"Frogs undergo distinct metamorphosis from an aquatic tadpole stage to a terrestrial adult frog. Earthworms have direct development; penguins are mammals with no larval stage; while some jellyfish have complex life cycles involving polyp and medusa stages, 'metamorphosis' in the standard zoological context of vertebrate exams most distinctly applies here."},{"id":1661,"text":"The presence of a diaphragm is a defining characteristic of which group of animals?","options":[{"label":"A","text":"Reptiles"},{"label":"B","text":"Birds"},{"label":"C","text":"Mammals"},{"label":"D","text":"Amphibians"}],"answer":2,"solution":"The diaphragm is a muscular partition separating the thoracic and abdominal cavities, essential for efficient breathing in mammals. Reptiles, birds, and amphibians rely on different mechanisms (rib movement or buccal pumping) and lack this specific structure."},{"id":1662,"text":"Which of the following structures is NOT part of the human male reproductive system?","options":[{"label":"A","text":"Seminal Vesicle"},{"label":"B","text":"Ovary"},{"label":"C","text":"Prostate Gland"},{"label":"D","text":"Epididymis"}],"answer":1,"solution":"The ovary is a female reproductive organ responsible for egg production. The seminal vesicle and prostate gland contribute to semen production in males, and the epididymis stores and matures sperm."},{"id":1663,"text":"What is the primary function of the stomata found on the epidermis of plant leaves?","options":[{"label":"A","text":"Gas exchange and transpiration"},{"label":"B","text":"Photosynthesis only"},{"label":"C","text":"Water absorption from soil"},{"label":"D","text":"Defense against herbivores"}],"answer":0,"solution":"Stomata are microscopic pores that open to allow carbon dioxide intake for photosynthesis and release oxygen and water vapor (transpiration). Photosynthesis occurs in chloroplasts within cells, not the pore itself; water absorption is done by roots; defense involves trichomes or chemical compounds."},{"id":1664,"text":"Which of the following structures in the human heart is responsible for preventing the backflow of blood from the left ventricle to the left atrium during systole?","options":[{"label":"A","text":"Tricuspid valve"},{"label":"B","text":"Mitral (bicuspid) valve"},{"label":"C","text":"Pulmonary semilunar valve"},{"label":"D","text":"Aortic semilunar valve"}],"answer":1,"solution":"The Mitral (bicuspid) valve is located between the left atrium and left ventricle, ensuring unidirectional flow. The Tricuspid valve is on the right side, while both semilunar valves prevent backflow into the arteries during ejection."},{"id":1665,"text":"In the context of plant physiology, which hormone is primarily responsible for promoting cell elongation and stem growth?","options":[{"label":"A","text":"Abscisic acid"},{"label":"B","text":"Gibberellins"},{"label":"C","text":"Cytokinins"},{"label":"D","text":"Ethylene"}],"answer":1,"solution":"Gibberellins stimulate cell division and elongation, leading to stem growth. Abscisic acid inhibits growth and promotes dormancy, Cytokinins promote cell division but not primarily elongation, and Ethylene regulates fruit ripening."},{"id":1666,"text":"Which of the following characteristics is unique to mammals among vertebrates?","options":[{"label":"A","text":"Presence of a three-chambered heart"},{"label":"B","text":"Feathers for flight"},{"label":"C","text":"Production of milk by mammary glands"},{"label":"D","text":"Cold-blooded metabolism"}],"answer":2,"solution":"Mammals are defined by the presence of mammary glands that produce milk. Amphibians and reptiles have different heart structures; birds have feathers but lay eggs; reptiles and amphibians are generally cold-blooded."},{"id":1667,"text":"The process by which ammonia produced from amino acid deamination is converted into urea in the liver is an example of:","options":[{"label":"A","text":"Glycolysis"},{"label":"B","text":"Urea Cycle"},{"label":"C","text":"Krebs Cycle"},{"label":"D","text":"Electron Transport Chain"}],"answer":1,"solution":"The Urea Cycle (Ornithine Cycle) specifically converts toxic ammonia into less toxic urea for excretion. Glycolysis breaks down glucose, the Krebs Cycle generates ATP from acetyl-CoA, and the Electron Transport Chain produces ATP via oxidative phosphorylation."},{"id":1668,"text":"Which of the following blood cells plays the most critical role in the immune response by engulfing pathogens?","options":[{"label":"A","text":"Erythrocytes"},{"label":"B","text":"Thrombocytes"},{"label":"C","text":"Neutrophils"},{"label":"D","text":"Plasma proteins"}],"answer":2,"solution":"Neutrophils are phagocytic white blood cells that engulf and destroy bacteria. Erythrocytes carry oxygen, Thrombocytes are involved in clotting, and Plasma proteins transport substances but do not directly engulf pathogens."},{"id":1669,"text":"In birds, the presence of a four-chambered heart is an adaptation that supports which physiological requirement?","options":[{"label":"A","text":"Cold-blooded metabolism"},{"label":"B","text":"Low oxygen demand"},{"label":"C","text":"High metabolic rate and endothermy"},{"label":"D","text":"Aquatic respiration"}],"answer":2,"solution":"A four-chambered heart allows complete separation of oxygenated and deoxygenated blood, supporting the high metabolic rate needed for flight and maintaining constant body temperature (endothermy). Cold-blooded animals typically have three-chambered hearts."},{"id":1670,"text":"Which of the following structures in the human ear is directly responsible for converting sound vibrations into electrical signals sent to the brain?","options":[{"label":"A","text":"Tympanic membrane"},{"label":"B","text":"Ossicles"},{"label":"C","text":"Organ of Corti"},{"label":"D","text":"Semicircular canals"}],"answer":2,"solution":"The Organ of Corti contains hair cells that transduce mechanical vibrations into nerve impulses. The Tympanic membrane receives sound waves, the Ossicles amplify them, and the Semicircular canals detect balance."},{"id":1671,"text":"Which of the following organisms exhibits a life cycle with distinct larval and adult stages involving metamorphosis?","options":[{"label":"A","text":"Earthworm"},{"label":"B","text":"Frog"},{"label":"C","text":"Snake"},{"label":"D","text":"Shark"}],"answer":1,"solution":"Frogs undergo complete metamorphosis from tadpole to adult frog. Earthworms, snakes (reptiles), and sharks generally do not exhibit such distinct metamorphic stages in their life cycles."}]}]};